import{_ as t,o as s,c as i,a5 as o}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/3.2-3.3-3.4-All-FR-Spec.md","filePath":"feature/3.2-3.3-3.4-All-FR-Spec.md"}'),n={name:"feature/3.2-3.3-3.4-All-FR-Spec.md"};function r(a,e,l,c,g,h){return s(),i("div",null,[...e[0]||(e[0]=[o('<h4 id="_3-2-1-sign-up-email-otp-verification" tabindex="-1">3.2.1 Sign Up (Email + OTP Verification) <a class="header-anchor" href="#_3-2-1-sign-up-email-otp-verification" aria-label="Permalink to &quot;3.2.1 Sign Up (Email + OTP Verification)&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when an unauthenticated Guest visits /register or /verify-otp after submitting the registration form.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: GUEST. Creates a new user account with default role USER.</li><li><strong>Purpose</strong>: Register a new account, verify email ownership via a one-time code, and hand the user to Sign In.</li><li><strong>Interface</strong>: Registration form with Full Name, Email, Password, Confirm Password; OTP Verification screen with a 6-digit code input and a Resend link.</li><li><strong>Data Processing</strong>: business-service validates email format and password policy, checks database uniqueness (BR-01), hashes password via BCrypt cost=12 (BR-02), creates user record, generates a 6-digit OTP with 10-minute expiry (BR-03), and dispatches the OTP email.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Registration Screen:</p><ul><li>Center: Text input for Full Name, Text input for Email, Password input with strength indicator, Confirm Password input.</li><li>Buttons: Primary button &quot;Create Account&quot;; Divider &quot;or&quot;; Button &quot;Sign up with Google&quot;.</li><li>Footer: Text link &quot;Already have an account? Log in&quot;.</li></ul><p>Figure — OTP Verification Screen:</p><ul><li>Center: 6 single-digit inputs for the OTP code, Verify button, Resend link with cooldown countdown.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required (register)</strong>: email, password, fullName.</li><li><strong>Input required (verify-otp)</strong>: email, otpCode.</li><li><strong>Input optional</strong>: confirmPassword (client-side check only, never sent to the server).</li><li><strong>System data</strong>: userId (UUID), defaultRole (USER), status (ACTIVE), otpCode, otpExpiry, createdAt (timestamp).</li><li><strong>Output (register)</strong>: userId.</li><li><strong>Output (verify-otp)</strong>: no payload body.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-01</strong>: Email is unique, case-insensitive. Duplicate -&gt; 409 EMAIL_ALREADY_EXISTS.</li><li><strong>BR-02</strong>: Password policy: minimum 8 characters + at least 1 digit; hashed with BCrypt cost=12; password is never logged or returned.</li><li><strong>BR-03</strong>: OTP is 6 digits, TTL 10 minutes, single-use; cleared after 5 failed attempts.</li><li><strong>BR-04</strong>: Resend OTP has a 60-second cooldown per email.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Empty required fields -&gt; Display: <strong>MSG02</strong></li><li>Invalid email format -&gt; Display: <strong>MSG04</strong></li><li>Password does not meet policy -&gt; Display: <strong>MSG05</strong></li><li>Passwords do not match -&gt; Display: <strong>MSG06</strong></li><li>Email already registered -&gt; Display: <strong>MSG08</strong></li><li>OTP wrong or expired -&gt; Display: <strong>MSG20</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The user navigates to /register and fills in Full Name, Email, Password, and Confirm Password.</li></ol></li><li><ol start="2"><li>The user clicks &quot;Create Account&quot;.</li></ol></li><li><ol start="3"><li>The system validates inputs and checks that email is unique in the database.</li></ol></li><li><ol start="4"><li>The system hashes the password with BCrypt cost=12 and creates a new user record.</li></ol></li><li><ol start="5"><li>The system generates a 6-digit OTP with a 10-minute expiry and sends it by email.</li></ol></li><li><ol start="6"><li>The system displays <strong>MSG10</strong> and redirects the user to the OTP Verification screen.</li></ol></li><li><ol start="7"><li>The user enters the OTP code and clicks Verify.</li></ol></li><li><ol start="8"><li>The system marks the email verified and redirects the user to Sign In.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: If the email is already registered, the system displays <strong>MSG08</strong>. 3.a2: The user switches to login or inputs another email.</li><li>3.b1: If password does not meet policy, the system displays <strong>MSG05</strong>. 3.b2: The user enters a valid password.</li><li>7.a1: If the OTP is wrong or expired, the system displays <strong>MSG20</strong>. 7.a2: The user retries or requests Resend.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>User record created in users collection with status = ACTIVE and role = USER.</li><li>OTP recorded with a 10-minute expiry until verified.</li><li>Email marked verified after successful OTP check.</li></ul><h4 id="_3-2-2-sign-in-with-email-phone-password" tabindex="-1">3.2.2 Sign In with Email/Phone + Password <a class="header-anchor" href="#_3-2-2-sign-in-with-email-phone-password" aria-label="Permalink to &quot;3.2.2 Sign In with Email/Phone + Password&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a Guest with an existing account visits /login and submits an identifier (email or phone number) together with a password.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: GUEST holding an existing account.</li><li><strong>Purpose</strong>: Authenticate with an email or phone number and a password, and obtain an access token plus a refresh token, unless two-factor authentication is enabled.</li><li><strong>Interface</strong>: Sign-in form with an identifier input (email or phone), a Password input, and a &quot;Forgot password&quot; link to Reset Password. Same screen carries the Google sign-in entry point.</li><li><strong>Data Processing</strong>: Resolves the identifier, checks account status, compares the password against the stored hash, records the sign-in, resolves the active workspace, and issues an access token plus a rotating refresh token; when 2FA is enabled, issues a challenge token instead.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Sign-in Screen:</p><ul><li>Identifier input (email or phone), Password input with reveal toggle, &quot;Forgot password&quot; link.</li><li>Submit button &quot;Sign in&quot;.</li><li>Divider &quot;Or continue with&quot;, Google sign-in button.</li><li>On success: stores access token, loads profile, navigates to Dashboard; toast <strong>MSG11</strong>.</li><li>When 2FA required: stores twoFactorToken in sessionStorage, navigates to /2fa-verify without storing any access token.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: identifier (email or phone), password.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: userId, role, status, twoFactorEnabled, lastLoginAt, workspaceId, accessToken, refreshToken.</li><li><strong>Output</strong>: access token, token type, expiry, a flag for 2FA required, refresh token as HttpOnly cookie. When 2FA required: a two-factor challenge token instead of access/refresh tokens.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-05</strong>: Anti-enumeration. Unknown identifier, wrong password, or account with no password all return the same 401 INVALID_CREDENTIALS.</li><li><strong>BR-06</strong>: Suspended account -&gt; 403 ACCOUNT_SUSPENDED. Deactivated account -&gt; 403 ACCOUNT_DEACTIVATED. Checked before password comparison.</li><li><strong>BR-07</strong>: Identifier auto-detected as email or phone; email matched case-insensitively, phone normalized before lookup.</li><li><strong>BR-08</strong>: Access token JWT RS256, 15-minute TTL. Refresh token HttpOnly cookie only, 30-day TTL. When 2FA enabled, no access/refresh token issued at this step; a challenge token is returned instead.</li><li><strong>BR-12</strong>: Refresh token jti checked against a blacklist; a token issued before the latest password change is rejected. Refresh accepted only via cookie. Missing/stale token -&gt; 401 REFRESH_TOKEN_INVALID; blacklisted token -&gt; 401 REFRESH_TOKEN_BLACKLISTED. Successful refresh rotates the token.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>identifier empty -&gt; Display: <strong>MSG02</strong></li><li>password empty -&gt; Display: <strong>MSG02</strong></li><li>identifier not a valid email or phone format -&gt; Display: <strong>MSG04</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The Guest opens /login and enters the identifier and password.</li></ol></li><li><ol start="2"><li>The system resolves the identifier to an account and checks the account status allows sign-in.</li></ol></li><li><ol start="3"><li>The system compares the submitted password with the stored hash.</li></ol></li><li><ol start="4"><li>With 2FA disabled, the system records the sign-in, resolves the active workspace, and issues an access token and a refresh token.</li></ol></li><li><ol start="5"><li>The system returns the tokens and sets the refresh token cookie.</li></ol></li><li><ol start="6"><li>The screen stores the access token, loads the profile, navigates to the Dashboard; toast <strong>MSG11</strong>.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Unknown identifier, wrong password, or no password (BR-05) -&gt; 401 INVALID_CREDENTIALS, toast <strong>MSG07</strong>. 2.a2: The Guest retries or uses &quot;Forgot password&quot;.</li><li>2.b1: Account status not ACTIVE/DEACTIVATED (BR-06) -&gt; 403 ACCOUNT_SUSPENDED, toast <strong>MSG09</strong>. 2.b2: The Guest contacts support.</li><li>2.c1: Account DEACTIVATED (BR-06) -&gt; 403 ACCOUNT_DEACTIVATED, toast <strong>MSG09</strong>. 2.c2: The Guest reactivates the account or contacts support.</li><li>4.a1: 2FA enabled (BR-08) -&gt; no access/refresh token issued; challenge token returned instead. 4.a2: The screen continues on the two-factor code screen.</li><li>5.a1: Refresh without cookie, or unusable/stale token (BR-12) -&gt; 401 REFRESH_TOKEN_INVALID, toast <strong>MSG22</strong>. 5.a2: Refresh with a blacklisted token (BR-12) -&gt; 401 REFRESH_TOKEN_BLACKLISTED, toast <strong>MSG22</strong>; either way the screen redirects to /login.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The sign-in is recorded and last sign-in time updated.</li><li>An access token and refresh token cookie are issued when 2FA is disabled.</li><li>A two-factor challenge token, and no tokens, is issued when 2FA is enabled.</li></ul><h4 id="_3-2-3-sign-in-with-google-oauth" tabindex="-1">3.2.3 Sign In with Google OAuth <a class="header-anchor" href="#_3-2-3-sign-in-with-google-oauth" aria-label="Permalink to &quot;3.2.3 Sign In with Google OAuth&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a Guest activates &quot;Sign in with Google&quot; on the sign-in or registration screen, sending the browser to GET /api/v1/auth/oauth/google.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: GUEST. The same handshake also serves a signed-in user linking Google to an existing account, outside this feature.</li><li><strong>Purpose</strong>: Let a user sign in with Google, create a local account on first use, and honour two-factor authentication when enabled.</li><li><strong>Interface</strong>: &quot;Sign in with Google&quot; button on the sign-in and registration screens. A redirect handshake: the browser leaves for Google&#39;s consent screen and returns to the application&#39;s callback route.</li><li><strong>Data Processing</strong>: Issues and stores a single-use state value, redirects to Google; on callback, validates the state, exchanges the code for a Google access token, fetches the Google profile, links or creates the local account, checks account status, then issues tokens or a two-factor challenge.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Google sign-in entry and return:</p><ul><li>Entry: &quot;Sign in with Google&quot; button on /login and /register.</li><li>Return: browser lands on /oauth-callback; reads token from the URL fragment, stores it, loads the profile, navigates to Dashboard; toast <strong>MSG11</strong> on success.</li><li>If callback carries error=ACCOUNT_SUSPENDED: dedicated toast (account suspended), navigates to /login.</li><li>If callback carries any other error, or no token: clears partial auth state, shows a generic OAuth-failure toast <strong>MSG12</strong>, navigates to /login.</li><li>When 2FA is enabled: browser lands on the two-factor code screen instead, carrying twoFactorToken as a query parameter.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: none entered by the user; Google supplies code and state (or error) on callback.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: providerId, email, emailVerifiedAt, passwordHash (absent for OAuth-only users), twoFactorEnabled, status, lastLoginAt, workspaceId, accessToken, refreshToken, twoFactorToken.</li><li><strong>Output</strong>: on success, a redirect carrying the access token in the URL fragment plus a refresh token cookie. When 2FA enabled, a redirect to the two-factor screen with a challenge token and no cookie. On a suspended/inactive account, a redirect with error=ACCOUNT_SUSPENDED. On any other failure, a redirect with error=oauth_failed.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-09</strong>: The state value is single-use, stored for 10 minutes, deleted on first read (CSRF protection). Missing/expired/unknown state -&gt; 400 OAUTH_STATE_INVALID, generic error toast <strong>MSG12</strong>.</li><li><strong>BR-10</strong>: Email is the linking anchor for OAuth; an existing account with the same email is reused and linked, no duplicate account created. Failed token exchange, or a Google profile without id/email or unverified email -&gt; 400 OAUTH_CODE_INVALID, toast <strong>MSG12</strong>.</li><li><strong>BR-11</strong>: One (provider, providerId) pair maps to exactly one user. First use creates a local account with email already verified and no password.</li><li><strong>BR-06</strong>: Suspended or inactive account -&gt; 403 ACCOUNT_SUSPENDED. Redirected distinctly to a dedicated error, separate from the generic OAuth-failure toast.</li><li><strong>BR-08</strong>: When 2FA is enabled, no access/refresh token issued; a two-factor challenge token is returned instead, same as email sign-in.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>User cancels consent or Google returns an error -&gt; no authorization code present -&gt; generic error toast <strong>MSG12</strong>, no further call to Google.</li><li>Google profile has no id/email, or email not verified -&gt; 400 OAUTH_CODE_INVALID, toast <strong>MSG12</strong>.</li><li>A network error calling Google -&gt; treated as a generic login failure, toast <strong>MSG12</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The Guest activates &quot;Sign in with Google&quot; on /login or /register.</li></ol></li><li><ol start="2"><li>The system generates a single-use state value, stores it for 10 minutes, and redirects the browser to Google&#39;s consent screen.</li></ol></li><li><ol start="3"><li>The user authenticates with Google and grants consent.</li></ol></li><li><ol start="4"><li>Google redirects the browser back to the application&#39;s callback route with code and state.</li></ol></li><li><ol start="5"><li>The system validates the authorization code is present, consumes the state, exchanges the code for a Google access token, and fetches the Google profile.</li></ol></li><li><ol start="6"><li>The system links the Google identity to an existing account with the same email, or creates a new verified account with no password.</li></ol></li><li><ol start="7"><li>The system checks the account status and, with 2FA disabled, records the sign-in, resolves the active workspace, and issues an access token and a refresh token.</li></ol></li><li><ol start="8"><li>The system sets the refresh token cookie and redirects to the callback page carrying the access token.</li></ol></li><li><ol start="9"><li>The screen reads the token, loads the profile, stores it, shows toast <strong>MSG11</strong>, and navigates to the Dashboard.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>4.a1: The user cancels consent or Google returns an error -&gt; generic error toast <strong>MSG12</strong>, no further call to Google. 4.a2: The Guest retries &quot;Sign in with Google&quot;.</li><li>5.a1: The state is missing, already used/expired, or belongs to another provider (BR-09) -&gt; 400 OAUTH_STATE_INVALID, toast <strong>MSG12</strong>. 5.a2: The Guest retries.</li><li>5.b1: Token exchange fails, or the Google profile has no email or an unverified email (BR-10) -&gt; 400 OAUTH_CODE_INVALID, toast <strong>MSG12</strong>. 5.b2: The Guest retries, or signs in with email/password instead.</li><li>5.c1: A network error occurs while calling Google -&gt; generic failure redirect, toast <strong>MSG12</strong>. 5.c2: The Guest retries.</li><li>7.a1: The account is suspended or deactivated (BR-06) -&gt; 403 ACCOUNT_SUSPENDED, dedicated suspended-account toast. 7.a2: The Guest contacts support.</li><li>7.b1: 2FA is enabled on the account (BR-08) -&gt; no access/refresh token issued; a challenge token is returned instead. 7.b2: The browser is sent to the two-factor code screen to complete sign-in.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The Google identity is linked to a local account, created on first use with email already verified and no password.</li><li>The sign-in is recorded, unless the user still has to complete two-factor verification.</li><li>An access token and a refresh-token cookie are issued, or a two-factor challenge token when 2FA is enabled.</li></ul><h4 id="_3-2-4-reset-password" tabindex="-1">3.2.4 Reset Password <a class="header-anchor" href="#_3-2-4-reset-password" aria-label="Permalink to &quot;3.2.4 Reset Password&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a user who forgot the password opens /forgot-password and submits an email address.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Unauthenticated USER who cannot sign in because the password is forgotten.</li><li><strong>Purpose</strong>: Restore access to the account by email through a single-use reset link, without revealing whether a given email is registered, and force sign-in again on every device once the password is changed.</li><li><strong>Interface</strong>: /forgot-password (email input) and /reset-password?token=... (new password + confirm password).</li><li><strong>Data Processing</strong>: forgot-password always returns 200 regardless of whether the email exists; if it exists, invalidates any earlier reset token, generates a new single-use token, and emails it. reset-password consumes the token atomically, hashes the new password, updates the last-password-change time, and writes an audit log entry.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Forgot Password / Reset Password screens:</p><ul><li>/forgot-password: email input, submit button. On success the form is replaced by a confirmation panel; the UI never says whether the email was actually found.</li><li>/reset-password: reads token from the URL; if absent, redirects to /forgot-password. New password input with strength meter, confirmation input, submit button.</li><li>Toasts: <strong>MSG15</strong> on forgot-password success (always), <strong>MSG16</strong>/<strong>MSG17</strong> on reset-password failure (invalid/expired vs. already-used token), <strong>MSG18</strong> on reset-password success, then redirected to /login.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: email (forgot-password step); token, newPassword (reset step).</li><li><strong>Input optional</strong>: confirmPassword — client-side check only, never sent to the server.</li><li><strong>System data</strong>: userId, email, passwordHash, lastPasswordChange, reset token (TTL up to 1 hour), reverse-index of the currently valid token per user.</li><li><strong>Output</strong>: no payload, 200, for both endpoints; the response never distinguishes success/failure cases that must stay silent.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-13</strong>: forgot-password always returns 200 whether or not the email exists. When it exists, any earlier token for that user is deleted first, then a new single-use token is generated with TTL up to 1 hour; only the most recently issued token is ever valid. reset-password with a missing/expired/superseded token -&gt; 400 RESET_TOKEN_INVALID; a token already consumed -&gt; 400 RESET_TOKEN_USED; a token for a deleted user -&gt; 400 RESET_TOKEN_INVALID.</li><li><strong>BR-02</strong>: New password must meet policy (min 8 characters, at least 1 digit); stored as a BCrypt hash.</li><li><strong>BR-12</strong>: After a successful reset, every refresh token issued before the change is rejected on its next use, forcing sign-in again on every device.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>email empty on /forgot-password -&gt; Display: <strong>MSG02</strong></li><li>email invalid format -&gt; Display: <strong>MSG04</strong></li><li>newPassword missing, under 8 characters, or missing a digit -&gt; Display: <strong>MSG05</strong></li><li>confirmPassword mismatch -&gt; Display: <strong>MSG06</strong></li><li>token missing from URL -&gt; client redirects to /forgot-password, no server call</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The user opens /forgot-password and submits the email address.</li></ol></li><li><ol start="2"><li>The system looks up the account by normalized email.</li></ol></li><li><ol start="3"><li>If found, the system deletes any earlier reset token, generates a new single-use token, stores it with TTL up to 1 hour, and sends the reset email.</li></ol></li><li><ol start="4"><li>The endpoint returns 200 regardless of whether the account was found. Toast <strong>MSG15</strong>.</li></ol></li><li><ol start="5"><li>The user opens the reset link, lands on /reset-password?token=..., and enters the new password and confirmation.</li></ol></li><li><ol start="6"><li>The system resolves and atomically deletes the reset token, hashes and saves the new password, and writes an audit log entry.</li></ol></li><li><ol start="7"><li>The endpoint returns 200. Toast <strong>MSG18</strong>; the user is redirected to /login.</li></ol></li><li><ol start="8"><li>Every refresh token issued before this reset is rejected on its next use, forcing sign-in again on that device.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: email empty -&gt; Display: <strong>MSG02</strong>. 1.a2: The user fills in the field and resubmits.</li><li>1.b1: email invalid format -&gt; Display: <strong>MSG04</strong>. 1.b2: The user corrects the format and resubmits.</li><li>2.a1: Email does not match any account (BR-13) -&gt; still 200, toast <strong>MSG15</strong>, no email sent. 2.a2: The user checks the inbox.</li><li>6.a1: Token missing, expired, or superseded (BR-13) -&gt; 400 RESET_TOKEN_INVALID, toast <strong>MSG16</strong>. 6.a2: The user requests a new reset link.</li><li>6.b1: Token already consumed (BR-13) -&gt; 400 RESET_TOKEN_USED, toast <strong>MSG17</strong>. 6.b2: The user requests a new reset link.</li><li>6.c1: Token decodes to a deleted account -&gt; 400 RESET_TOKEN_INVALID, toast <strong>MSG16</strong>. 6.c2: The user requests a new reset link.</li><li>6.d1: newPassword fails the policy (BR-02) -&gt; Display: <strong>MSG05</strong>. 6.d2: The user corrects the password and resubmits.</li><li>6.e1: confirmPassword mismatch -&gt; Display: <strong>MSG06</strong>, submit blocked. 6.e2: The user re-types the confirmation.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>On a successful reset, passwordHash is replaced and lastPasswordChange is set; an audit log row exists; the consumed token and its reverse-index are deleted.</li><li>On any forgot-password call, exactly one valid reset token exists per account at a time; the response is always 200.</li><li>Refresh tokens issued before the reset are rejected on their next use (BR-12), independent of any explicit logout.</li></ul><h4 id="_3-2-5-change-password" tabindex="-1">3.2.5 Change Password <a class="header-anchor" href="#_3-2-5-change-password" aria-label="Permalink to &quot;3.2.5 Change Password&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user opens the change-password section under Settings &gt; Security and submits the current password together with a new password and its confirmation.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any authenticated USER changing their own password. Applies to any account that already has a password set.</li><li><strong>Purpose</strong>: Let a signed-in user change the password after proving knowledge of the current one, without ending the current session.</li><li><strong>Interface</strong>: A form on Settings &gt; Security with three fields — Current Password, New Password, Confirm New Password — and a submit button.</li><li><strong>Data Processing</strong>: Identifies the caller from the access token, verifies the current password against the stored hash, refuses a new password identical to the current one, replaces the password hash, updates the last-password-change time, and records an audit log event.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Change Password (Settings &gt; Security):</p><ul><li>A card titled &quot;Change Password&quot; with three password inputs: Current Password, New Password, Confirm New Password (client-only confirmation, not sent to the server).</li><li>A single submit button, loading state while in flight.</li><li>On success: a toast confirms the change and the user is navigated to the dashboard; the current session stays signed in.</li><li>On failure: an error message is shown and the form remains filled in for correction.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: currentPassword, newPassword; Authorization Bearer header.</li><li><strong>Input optional</strong>: confirmNewPassword — client-side only, never sent to the server.</li><li><strong>System data</strong>: userId (from the access token), user.passwordHash, user.lastPasswordChange, the audit log entry.</li><li><strong>Output</strong>: no payload, 200.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-02</strong>: Password policy — minimum 8 characters and at least 1 digit; hashed with BCrypt cost=12; never logged or returned.</li><li><strong>BR-88</strong>: Check order: (1) verify currentPassword against the stored hash — mismatch -&gt; 400 WRONG_CURRENT_PASSWORD; (2) only then compare newPassword to the same hash — a match -&gt; 400 SAME_AS_CURRENT_PASSWORD; (3) only then hash and persist the new password.</li><li><strong>BR-12</strong>: Changing the password sets lastPasswordChange = now. A refresh token issued before this timestamp is rejected on its next use, invalidating every outstanding refresh token on every device, even though the current session remains valid.</li><li><strong>BR-89</strong>: The same audit action is reused for both Reset Password and Change Password; there is no distinct &quot;password changed&quot; action.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>currentPassword or newPassword empty -&gt; Display: <strong>MSG02</strong></li><li>newPassword under 8 characters or missing a digit -&gt; Display: <strong>MSG05</strong></li><li>confirmNewPassword mismatch -&gt; Display: <strong>MSG06</strong></li><li>Missing or malformed Authorization header -&gt; 401 INVALID_CREDENTIALS</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The user opens Settings &gt; Security and enters the current password, the new password, and the confirmation.</li></ol></li><li><ol start="2"><li>The client checks the confirmation matches the new password, then submits.</li></ol></li><li><ol start="3"><li>The system resolves the caller&#39;s userId from the access token and loads the account.</li></ol></li><li><ol start="4"><li>The system verifies currentPassword against the stored hash.</li></ol></li><li><ol start="5"><li>The system compares newPassword against the same hash and rejects it if identical.</li></ol></li><li><ol start="6"><li>The system replaces passwordHash with the BCrypt hash of newPassword, sets lastPasswordChange = now, and writes an audit log entry.</li></ol></li><li><ol start="7"><li>The system returns 200. The client shows a success toast and navigates to the dashboard; the current session stays signed in, while every outstanding refresh token is invalidated.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Missing or malformed Authorization header -&gt; 401 INVALID_CREDENTIALS. 2.a2: The user is signed out and returned to login.</li><li>3.a1: The account referenced by the token no longer exists -&gt; 404 USER_NOT_FOUND. 3.a2: The user is signed out and must sign in again.</li><li>4.a1: currentPassword does not match the stored hash, checked first -&gt; 400 WRONG_CURRENT_PASSWORD, Display: <strong>MSG19</strong>. 4.a2: The user re-enters the current password.</li><li>5.a1: newPassword is identical to currentPassword, checked only after step 4 passes -&gt; 400 SAME_AS_CURRENT_PASSWORD. 5.a2: The user enters a different new password.</li><li>1.a1: newPassword fails the policy check -&gt; Display: <strong>MSG05</strong>. 1.a2: The user corrects the password and resubmits.</li><li>1.b1: currentPassword or newPassword empty -&gt; Display: <strong>MSG02</strong>. 1.b2: The user fills in the missing field and resubmits.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>user.passwordHash is replaced and user.lastPasswordChange is updated to the change time.</li><li>An audit log entry is recorded for the user.</li><li>The current session remains valid and signed in.</li><li>Every refresh token issued before the change, on this device or any other, is rejected on its next use; the user must sign in again on those other sessions.</li></ul><h4 id="_3-2-6-otp-verification-phone-linking" tabindex="-1">3.2.6 OTP Verification (Phone Linking) <a class="header-anchor" href="#_3-2-6-otp-verification-phone-linking" aria-label="Permalink to &quot;3.2.6 OTP Verification (Phone Linking)&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user opens &quot;Link phone&quot; on their profile, enters a phone number, and then enters the six-digit code they receive.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: A signed-in user (Bearer token required) linking a phone number to their account.</li><li><strong>Purpose</strong>: Confirm ownership of a phone number with a short-lived one-time code before attaching it to the account.</li><li><strong>Interface</strong>: A &quot;Link phone&quot; modal on the Profile page, with two steps: a phone number input, then a six-digit code input.</li><li><strong>Data Processing</strong>: Normalizes the phone number, generates a 6-digit numeric code, stores the code with the phone in Redis with a 10-minute TTL, enforces a 60-second resend cooldown and a 5-attempt wrong-code limit, and on success sets user.phone. The code is delivered by email to the account&#39;s own address, not by SMS.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Link Phone modal (Profile page):</p><ul><li>Step &quot;phone&quot;: a phone number input plus Cancel / &quot;Send OTP&quot; buttons; disabled while empty or sending.</li><li>Step &quot;otp&quot;: a hint line plus a six-digit code input, plus Cancel / &quot;Verify&quot; buttons; disabled while empty or verifying.</li><li>On send success: toast, advances to the &quot;otp&quot; step.</li><li>On verify success: toast, closes and resets the modal.</li><li>On any error: toast built from the error response.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: phone (link step); otpCode (verify step). Both endpoints require a valid Authorization Bearer header.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: userId (from the access token), pending code + phone stored in Redis (TTL 10 min), a resend-cooldown marker (TTL 60s), a wrong-attempt counter (TTL 10 min), user.phone.</li><li><strong>Output</strong>: no payload, 200, on both endpoints.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-03</strong>: Numeric OTP is 6 digits, TTL 10 minutes, single-use, cleared on success.</li><li><strong>BR-04</strong>: Resend has a 60-second cooldown, scoped per userId.</li><li><strong>BR-07</strong>: Phone must normalize to a valid E.164 number, else 400 INVALID_PHONE. Phone already used by a different user -&gt; 409 PHONE_ALREADY_IN_USE. A repeat link call inside the cooldown -&gt; 429 RATE_LIMIT_EXCEEDED, the pending code is not replaced. Wrong code increments the attempt counter; on the 5th wrong attempt both the code and the counter are deleted and the answer is 400 OTP_TOO_MANY_ATTEMPTS; below 5, 400 OTP_INVALID. Correct code deletes both keys, re-checks phone uniqueness (race guard), and sets user.phone.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>phone empty or invalid format -&gt; Display: <strong>MSG02</strong></li><li>otpCode empty -&gt; Display: <strong>MSG02</strong></li><li>otpCode invalid or expired -&gt; Display: <strong>MSG20</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The signed-in user opens the &quot;Link phone&quot; modal and enters a phone number.</li></ol></li><li><ol start="2"><li>The client calls the link-phone endpoint with the Bearer token.</li></ol></li><li><ol start="3"><li>The system normalizes the phone number, checks it is not already used by another user, generates a 6-digit code, stores it with the phone in Redis (TTL 10 min), starts the 60s cooldown, and emails the code.</li></ol></li><li><ol start="4"><li>The user enters the code in the modal&#39;s second step.</li></ol></li><li><ol start="5"><li>The client calls the verify endpoint with the Bearer token.</li></ol></li><li><ol start="6"><li>The system matches the code, clears the pending code and attempt counter, re-checks phone uniqueness, and sets user.phone.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: phone fails normalization -&gt; 400 INVALID_PHONE, Display: <strong>MSG02</strong>. 2.a2: The user corrects the phone number and resubmits.</li><li>2.b1: Phone already used by another user -&gt; 409 PHONE_ALREADY_IN_USE. 2.b2: The user enters a different phone number.</li><li>2.c1: link-phone called again inside the 60s cooldown -&gt; 429 RATE_LIMIT_EXCEEDED. 2.c2: The user waits for the cooldown to elapse.</li><li>5.a1: No pending code (never requested or expired) -&gt; 400 OTP_INVALID, Display: <strong>MSG20</strong>. 5.a2: The user requests a new code.</li><li>5.b1: Wrong code, below 5 attempts -&gt; 400 OTP_INVALID, Display: <strong>MSG20</strong>. 5.b2: The user re-enters the code.</li><li>5.c1: 5th wrong attempt -&gt; 400 OTP_TOO_MANY_ATTEMPTS; the pending code is discarded. 5.c2: The user must restart from step 1 for a new code.</li><li>5.d1: Correct code, but the phone was taken by another user meanwhile -&gt; 409 PHONE_ALREADY_IN_USE. 5.d2: The user enters a different phone number and restarts.</li><li>Missing/expired Bearer token on either call -&gt; 401 INVALID_CREDENTIALS; user is redirected to sign in.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>On success: user.phone is set to the normalized number; the pending code and attempt counter are cleared.</li><li>On failure: no change to user.phone; Redis state reflects the specific failure path.</li></ul><h4 id="_3-2-7-two-factor-authentication-2fa-totp" tabindex="-1">3.2.7 Two-Factor Authentication (2FA, TOTP) <a class="header-anchor" href="#_3-2-7-two-factor-authentication-2fa-totp" aria-label="Permalink to &quot;3.2.7 Two-Factor Authentication (2FA, TOTP)&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user enables or disables 2FA from the Security settings page, or when a user who already has it enabled completes the password step or Google sign-in and is redirected to the code-entry screen.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: USER — signed in when enabling, confirming, or disabling; holding only a short-lived two-factor token (no access token) when verifying at sign-in.</li><li><strong>Purpose</strong>: Add a second factor based on time-based one-time codes, so every sign-in method requires something the user holds in addition to the password.</li><li><strong>Interface</strong>: Security page — &quot;Enable 2FA&quot; revealing a QR code and a 6-digit code input to confirm; &quot;Disable 2FA&quot; requiring the current code; a single 6-digit code screen shown during sign-in when 2FA is enabled.</li><li><strong>Data Processing</strong>: Generates a TOTP secret and holds it pending in Redis until a correct code confirms it; only then is the secret persisted and 2FA marked enabled. Verifying a code always checks it against the TOTP algorithm, then always runs the attempt-lockout check: a wrong code increments a per-user counter (TTL 10 minutes), and the 5th wrong code within that window returns a lockout error instead of an invalid-code error; a correct code clears the counter.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Two-Factor Authentication screens:</p><ul><li>Security page 2FA card: not enabled shows &quot;Enable 2FA&quot;; mid-setup shows a QR code plus a 6-digit code input with Confirm/Cancel; enabled shows a &quot;Disable 2FA&quot; button; confirming disable shows a 6-digit code input with Confirm/Cancel.</li><li>Verify screen: 6 single-digit inputs, a Verify button, and a &quot;Back to login&quot; link. Reached only when a two-factor token is present; otherwise redirects to /login.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: code (6-digit) for confirm/disable/verify; twoFactorToken for verify. Setup takes no body.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: userId, totpSecret, twoFactorEnabled, the pending secret (Redis, TTL 10 min), the wrong-attempt counter (Redis, TTL 10 min), twoFactorToken, lastLoginAt, workspaceId.</li><li><strong>Output</strong>: otpAuthUrl (setup); nothing (confirm/disable); access token, token type, expiry, and a refresh-token cookie (verify).</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-15</strong>: TOTP, 6-digit code, 30-second step, ±1-step tolerance. setup: 404 USER_NOT_FOUND if missing; 400 TWO_FA_ALREADY_ENABLED if already enabled. confirm: same checks plus 400 TWO_FA_NOT_ENABLED if no pending secret; 400 TWO_FA_CODE_INVALID on mismatch. disable: 400 TWO_FA_NOT_ENABLED if not enabled; 400 TWO_FA_CODE_INVALID on mismatch. No recovery-code mechanism exists; a lost authenticator requires an administrator to disable 2FA manually.</li><li><strong>BR-86</strong>: Wrong 2FA code is limited to 5 attempts within a 10-minute window, shared across confirm/disable/verify for the same user. The 5th wrong code returns 429 TWO_FA_TOO_MANY_ATTEMPTS instead of 400 TWO_FA_CODE_INVALID; a correct code clears the counter immediately.</li><li><strong>BR-17</strong>: Mandatory 2FA for higher roles is not implemented; 2FA is opt-in for every role today.</li><li><strong>BR-05</strong>: Verify at sign-in requires the token to parse and carry the 2FA claim type, else 401 TWO_FA_TOKEN_INVALID; subject must resolve to an existing user, else the same generic error. Account status checked next: 403 ACCOUNT_SUSPENDED or 403 ACCOUNT_DEACTIVATED. If 2FA was disabled meanwhile -&gt; 400 TWO_FA_NOT_ENABLED. On success, sign-in completes exactly as a normal login.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>code empty or not a 6-digit number -&gt; Display: <strong>MSG02</strong></li><li>code well-formed but does not match the current window -&gt; 400 TWO_FA_CODE_INVALID, Display: <strong>MSG20</strong> (or 429 on the 5th wrong code within 10 minutes)</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>Signed-in user opens Security settings and clicks &quot;Enable 2FA&quot;.</li></ol></li><li><ol start="2"><li>The system loads the account, confirms 2FA is not already enabled, generates a TOTP secret, stores it pending in Redis (TTL 10 min), and returns the QR provisioning URL.</li></ol></li><li><ol start="3"><li>The client renders the QR code; the user scans it with an authenticator app.</li></ol></li><li><ol start="4"><li>The user enters the 6-digit code shown by the app and submits.</li></ol></li><li><ol start="5"><li>The system re-checks not-already-enabled, reads the pending secret, verifies the code; a wrong code goes through the attempt-lockout check; on match it clears the counter, persists the secret, sets 2FA enabled, and deletes the pending key. Toast <strong>MSG24</strong>.</li></ol></li><li><ol start="6"><li>On a later sign-in, the login step sees 2FA enabled, issues a two-factor token, and returns it — no access/refresh token yet. The client redirects to the verify screen.</li></ol></li><li><ol start="7"><li>The user enters the code from the app on the verify screen and submits.</li></ol></li><li><ol start="8"><li>The system validates the token, loads the user, checks status, verifies the code (wrong code goes through the lockout check), and on match completes sign-in: clears the counter, issues access and refresh tokens, sets the refresh cookie.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Setup requested for an account that no longer exists -&gt; 404 USER_NOT_FOUND.</li><li>2.b1: Setup requested while 2FA is already enabled -&gt; 400 TWO_FA_ALREADY_ENABLED. 2.b2: The user disables 2FA first, then starts setup again.</li><li>5.a1: Confirm while already enabled (double submit) -&gt; 400 TWO_FA_ALREADY_ENABLED.</li><li>5.b1: Confirm with no pending secret, never called setup or TTL expired -&gt; 400 TWO_FA_NOT_ENABLED. 5.b2: The user restarts setup for a fresh QR code.</li><li>5.c1: Confirm with a wrong code -&gt; 400 TWO_FA_CODE_INVALID, Display: <strong>MSG20</strong>; the pending secret is kept for retry. 5.c2: The user re-enters the code.</li><li>5.d1: Confirm with the 5th wrong code within 10 minutes (BR-86) -&gt; 429 TWO_FA_TOO_MANY_ATTEMPTS. 5.d2: The user waits for the window to lapse before retrying.</li><li>Disable.a1: Disable while 2FA is not enabled -&gt; 400 TWO_FA_NOT_ENABLED.</li><li>Disable.b1: Disable with a wrong code -&gt; 400 TWO_FA_CODE_INVALID, Display: <strong>MSG20</strong>. On success, toast <strong>MSG25</strong>.</li><li>Disable.c1: Disable with the 5th wrong code within 10 minutes -&gt; 429 TWO_FA_TOO_MANY_ATTEMPTS.</li><li>8.a1: Verify with an unparseable token, wrong claim, or unresolvable subject -&gt; 401 TWO_FA_TOKEN_INVALID, toast <strong>MSG22</strong>. 8.a2: The user is returned to /login.</li><li>8.b1: Verify against a suspended or deactivated account -&gt; 403 ACCOUNT_SUSPENDED / 403 ACCOUNT_DEACTIVATED. 8.b2: The user contacts support.</li><li>8.c1: 2FA was disabled between login and verify -&gt; 400 TWO_FA_NOT_ENABLED. 8.c2: The user signs in normally.</li><li>8.d1: Verify with a wrong code -&gt; 400 TWO_FA_CODE_INVALID, Display: <strong>MSG20</strong>. 8.d2: The user re-enters the code.</li><li>8.e1: Verify with the 5th wrong code within 10 minutes -&gt; 429 TWO_FA_TOO_MANY_ATTEMPTS. 8.e2: The user waits for the window to lapse, then signs in again.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>On enabling: totpSecret is stored, twoFactorEnabled=true, the pending-setup key is deleted, and the attempt counter is cleared.</li><li>On disabling: totpSecret is cleared and twoFactorEnabled=false; the attempt counter is cleared.</li><li>On a successful verify at sign-in: sign-in completes as in normal login and the attempt counter is cleared.</li><li>On a wrong code in any of the three flows: the attempt counter is incremented; on the 5th wrong code within 10 minutes it is deleted and further calls fail with 429 until success or the window naturally expires.</li></ul><h4 id="_3-2-8-sign-out-logout" tabindex="-1">3.2.8 Sign Out (Logout) <a class="header-anchor" href="#_3-2-8-sign-out-logout" aria-label="Permalink to &quot;3.2.8 Sign Out (Logout)&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user clicks &quot;Log out&quot; in the account/navbar menu (or the dashboard&#39;s logout button).</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any authenticated USER.</li><li><strong>Purpose</strong>: End the current session. Blacklists the current access and refresh token server-side and records a LOGOUT audit event, then clears local client state and redirects to /login.</li><li><strong>Interface</strong>: A &quot;Log out&quot; menu item / icon button in the Navbar and in the Dashboard page header.</li><li><strong>Data Processing</strong>: The client fires the logout call (fire-and-forget, not awaited) and, independent of its outcome, immediately clears local auth state and navigates to /login. The backend reads the access token header, the refresh token cookie, and request metadata, blacklists the access token (best-effort) and the refresh token (best-effort), writes an audit log when the access token yielded a user id, clears the refresh cookie, and returns 200.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Sign Out entry points (no dedicated Sign Out screen exists):</p><ul><li>Navbar: a &quot;Log out&quot; icon button inside the account area.</li><li>Dashboard page header: a separate &quot;Log out&quot; button that clears local state directly, without calling the logout endpoint.</li><li>After either action, the user becomes unauthenticated and any protected route redirects to /login.</li><li>A 401 response interceptor also forces logout automatically on session expiry, with toast <strong>MSG22</strong>; this path also does not call the logout endpoint.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required (backend)</strong>: Authorization Bearer header. The refresh token cookie is optional.</li><li><strong>Input optional (backend)</strong>: IP address and user-agent headers, used for the audit record.</li><li><strong>Input (frontend)</strong>: none — no body is sent; the header and cookie are attached automatically.</li><li><strong>System data</strong>: userId resolved from the access token&#39;s subject (only if it parses); the token&#39;s jti for blacklisting; the caller&#39;s ipAddress/userAgent.</li><li><strong>Output</strong>: no payload, 200. The refresh token cookie is cleared.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-14</strong>: Sign-out blacklists both access and refresh token jti values and clears the refresh cookie. Each blacklisting step is independently best-effort — either one failing (expired, malformed, wrong signature) is swallowed silently and does not fail the request. The refresh cookie is cleared unconditionally on every successful response. The frontend call itself is best-effort and swallows any error, proceeding to clear local state regardless.</li><li><strong>BR-16</strong>: Security events (LOGIN, LOGOUT, PASSWORD_RESET) are always persisted to the audit log with IP + user agent. For logout, the audit row is written only if the access token successfully parsed to a userId; otherwise no row is written but success is still reported.</li><li><strong>BR-90</strong>: Only the tokens for the current device/session are invalidated; refresh tokens held by other devices are unaffected, unlike a password change which invalidates every refresh token.</li><li><strong>BR-91</strong>: Missing or malformed Authorization header is the one case that is not best-effort on the backend, though this never surfaces to the user since the client clears local state and navigates away regardless.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Authorization header missing, or not starting with &quot;Bearer &quot; -&gt; 401 INVALID_CREDENTIALS.</li><li>Expired or unparsable access token (header well-formed) -&gt; not an error; sign-out still returns 200.</li><li>Missing, expired, or unparsable refresh token -&gt; not an error; sign-out still returns 200.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The user clicks &quot;Log out&quot; in the Navbar.</li></ol></li><li><ol start="2"><li>The client calls the logout endpoint with the Bearer header and refresh cookie sent automatically, without awaiting it, and swallows any rejection.</li></ol></li><li><ol start="3"><li>Independent of that outcome, the client clears local auth/workspace state and navigates to /login without waiting for the API response.</li></ol></li><li><ol start="4"><li>The backend validates the Authorization header format, strips the prefix, and calls the service.</li></ol></li><li><ol start="5"><li>The service parses the access token; on success it extracts the userId and blacklists the access token&#39;s jti.</li></ol></li><li><ol start="6"><li>If a refresh token is present, the service blacklists its jti too, independent of step 5&#39;s outcome.</li></ol></li><li><ol start="7"><li>If a userId was resolved in step 5, the service writes a LOGOUT audit log with ipAddress and userAgent.</li></ol></li><li><ol start="8"><li>The backend clears the refresh token cookie and returns 200 with no data.</li></ol></li><li><ol start="9"><li>By the time the response arrives, the user is typically already on /login; no toast is shown for the success case.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>4.a1: Authorization header missing or malformed -&gt; the backend returns 401 INVALID_CREDENTIALS without calling the service. 4.a2: The frontend&#39;s error handler swallows it; the client still clears local state and navigates to /login with no user-facing error.</li><li>5.a1: Access token present but expired or fails to parse -&gt; caught and ignored; userId stays null; sign-out proceeds as idempotent success, no audit row written. 5.a2: Refresh token blacklisting still runs if present.</li><li>6.a1: Refresh token absent, expired, or fails to parse -&gt; caught and ignored; sign-out still returns 200.</li><li>N.a1: The logout call fails on the network (offline, timeout, server down) -&gt; the client proceeds exactly as in the success case: local state cleared, redirect to /login, no error toast; the server-side token remains valid until natural expiry.</li><li>N.a2: A 401 from any API call triggers a forced local-only logout with toast <strong>MSG22</strong> (&quot;session expired&quot;); this path does not call the logout endpoint.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The access token&#39;s and refresh token&#39;s jti values are blacklisted server-side (best-effort), the refresh cookie is cleared, and, when the access token was resolvable, a LOGOUT audit row exists.</li><li>Regardless of the API call&#39;s outcome, local auth/workspace state is cleared and the user is redirected to /login.</li><li>Sessions on other devices are unaffected.</li><li>If the API call failed, the server-side token may remain valid until natural expiry, but the user is signed out of the current browser session either way.</li></ul><h4 id="_3-2-9-deactivate-account" tabindex="-1">3.2.9 Deactivate Account <a class="header-anchor" href="#_3-2-9-deactivate-account" aria-label="Permalink to &quot;3.2.9 Deactivate Account&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user activates &quot;Deactivate&quot; in the Danger Zone of the profile screen and confirms the dialog with their password, or, for an account with no password, with a one-time code sent to their email.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: USER who is signed in, either with a password or as an OAuth-only account with no password.</li><li><strong>Purpose</strong>: Let a user disable their own account (soft delete) after proving identity with the password or a one-time email code, and immediately cut off active sessions.</li><li><strong>Interface</strong>: Danger Zone section on the profile page with a confirmation dialog. Accounts with a password show a password field; accounts without one show a &quot;Send code&quot; button and, once sent, a six-digit code field.</li><li><strong>Data Processing</strong>: Resolves the caller from the Bearer access token, reads the refresh token cookie and the raw access token. Loads the user, verifies identity via the password or OTP branch, checks the caller does not own any ACTIVE agency, sets user.status = DEACTIVATED and saves, then blacklists the caller&#39;s access token and refresh token (best-effort) so active sessions are cut off immediately.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Deactivate Account (Profile, Danger Zone):</p><ul><li>A red-bordered &quot;Danger Zone&quot; card with a &quot;Deactivate&quot; button that opens the confirm dialog.</li><li>If the account has a password: the dialog shows a password input.</li><li>If the account has no password: the dialog shows a &quot;Send code&quot;/&quot;Resend code&quot; button followed by an OTP input.</li><li>Cancel and a destructive &quot;Confirm Deactivate&quot; button, disabled until the relevant field is non-empty or while the request is in flight.</li><li>On success the client clears the local session and returns to /login.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: Bearer access token. Exactly one of password or otpCode, selected by the account&#39;s own state, not by which field the client sends.</li><li><strong>Input optional</strong>: both password and otpCode are optional at the request level; the service enforces which one is actually required and ignores the other. The refresh token cookie is optional.</li><li><strong>System data</strong>: userId (from token), user.passwordHash, user.status, deactivate OTP (Redis, TTL 10 min), agencies owned by the user and their status, the caller&#39;s raw access token and refresh token.</li><li><strong>Output</strong>: no payload, 200.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-22</strong>: Deactivation sets user.status = DEACTIVATED and blacklists outstanding tokens so active sessions are cut off. After the status update, the service blacklists the caller&#39;s access token and refresh token, each wrapped in a best-effort try/catch that ignores a malformed or absent token. A subsequent login or refresh is also rejected with 403 ACCOUNT_DEACTIVATED, but the blacklist call is what makes cut-off immediate rather than only on next refresh/expiry.</li><li><strong>BR-23</strong>: The last active OWNER of an Agency cannot self-deactivate. After identity is confirmed, the system checks for any Agency owned by the caller with status ACTIVE; if one exists -&gt; 409 AGENCY_OWNERSHIP_ACTIVE, account left unchanged.</li><li><strong>BR-92</strong>: Identity confirmation: no password on file -&gt; OTP branch (missing, expired, or mismatched code -&gt; 400 OTP_INVALID; a match deletes the key so it cannot be reused). Password on file -&gt; password branch (mismatch -&gt; 400 WRONG_CURRENT_PASSWORD). The field not used by the branch is ignored.</li><li><strong>BR-93</strong>: sendDeactivateOtp generates a 6-digit OTP (TTL 10 min) and emails it; there is no resend cooldown on this endpoint, unlike the analogous email-OTP and phone-OTP flows.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Missing or malformed access token -&gt; 401 INVALID_CREDENTIALS, toast <strong>MSG22</strong></li><li>password empty (password branch) -&gt; Display: <strong>MSG02</strong></li><li>otpCode empty or malformed (OTP branch) -&gt; Display: <strong>MSG02</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The user opens the Danger Zone on the profile page and activates &quot;Deactivate&quot;.</li></ol></li><li><ol start="2"><li>The client resolves whether the account has a password and shows the matching field.</li></ol></li><li><ol start="3"><li>For an OAuth-only account, the user first clicks &quot;Send code&quot;; the system generates and emails a 6-digit OTP (TTL 10 min).</li></ol></li><li><ol start="4"><li>The user supplies the password or the OTP and confirms, with the Bearer header and, if present, the refresh cookie sent automatically.</li></ol></li><li><ol start="5"><li>The system resolves the caller and extracts the raw access token and refresh token.</li></ol></li><li><ol start="6"><li>The system loads the user and verifies the password or the OTP depending on whether a password is set.</li></ol></li><li><ol start="7"><li>The system checks for an ACTIVE agency owned by the user (BR-23); none found.</li></ol></li><li><ol start="8"><li>The system sets user.status = DEACTIVATED and saves.</li></ol></li><li><ol start="9"><li>The system blacklists the access token and, if present, the refresh token, ignoring failures on a malformed/absent token.</li></ol></li><li><ol start="10"><li>200 OK; the client clears the local session, redirects to /login, toast <strong>MSG91</strong>.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>5.a1: Missing or invalid access token -&gt; 401 INVALID_CREDENTIALS, toast <strong>MSG22</strong>. 5.a2: The user signs in again.</li><li>6.a1: Account referenced by the token no longer exists -&gt; 404 USER_NOT_FOUND, toast <strong>MSG38</strong>. 6.a2: The user signs in again with a valid account.</li><li>6.b1: Password branch, wrong password -&gt; 400 WRONG_CURRENT_PASSWORD, Display: <strong>MSG19</strong>. 6.b2: The user re-enters the password.</li><li>6.c1: OTP branch, code missing, expired, never requested, or mismatched -&gt; 400 OTP_INVALID, Display: <strong>MSG20</strong>. 6.c2: The user requests a new code and re-enters it.</li><li>7.a1: The user owns at least one ACTIVE agency (BR-23) -&gt; 409 AGENCY_OWNERSHIP_ACTIVE, toast <strong>MSG38</strong>. 7.a2: The user transfers agency ownership first; if the OTP branch was used, a new code must be requested before retrying.</li><li>9.a1: Access token malformed, expired, or absent at the blacklist step -&gt; caught and ignored; deactivation still succeeds. 9.a2: Same handling for a malformed/absent refresh cookie.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>user.status = DEACTIVATED; all related rows (agencies, workspace memberships, etc.) are kept — this is a soft delete.</li><li>The OTP, when the OTP branch was used, is consumed and cannot be reused.</li><li>The caller&#39;s access token and refresh token (if present) are blacklisted, so the currently active session is cut off immediately.</li><li>A subsequent login or refresh attempt is also rejected with 403 ACCOUNT_DEACTIVATED, independent of the blacklist.</li></ul><h4 id="_3-3-1-view-user-profile" tabindex="-1">3.3.1 View User Profile <a class="header-anchor" href="#_3-3-1-view-user-profile" aria-label="Permalink to &quot;3.3.1 View User Profile&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user opens the Profile screen at /profile.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any authenticated user (role USER); a user reads only their own profile.</li><li><strong>Purpose</strong>: Display the personal information the system holds for the signed-in user, so the user can verify it.</li><li><strong>Interface</strong>: The Profile screen at /profile, a single page combining the read-only view and the edit form. Edit toggles the section into edit mode (see FR 3.3.2). In view mode every field is text-only.</li><li><strong>Data Processing</strong>: The system resolves the caller&#39;s identity from the access token only, loads the matching user record, resolves the system role, resolves the current workspace, and derives timezone and notification preferences from the preferences data on the user record. No data is modified.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Profile Screen (/profile, view mode):</p><ul><li>Header: page title &quot;Profile&quot;.</li><li>Top card: avatar image (or default initials avatar), full name, email, a &quot;Verified&quot; badge, and an Edit button.</li><li>Two-column grid: system role, phone number (with a change/add-phone link), member-since date, last-login date, job title (professionalTitle), working language, timezone, bio, portfolio URLs (list of links) — each showing an empty-state placeholder when not set.</li><li>Side panel: Danger Zone card with a Deactivate Account button (separate flow, not part of this FR).</li><li>Buttons: Edit — switches the profile card into edit mode (FR 3.3.2).</li><li>Footer: none.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: None — identity is derived from the access token; the caller cannot supply another user&#39;s identifier.</li><li><strong>Input optional</strong>: None.</li><li><strong>System data</strong>: users (userId, email, fullName, avatarUrl, phone, professionalTitle, bio, portfolioUrls, workingLanguage, preferences JSON, createdAt); user_system_roles (system role); workspace_members (workspaceId).</li><li><strong>Output</strong>: userId, email, fullName, avatarUrl, phone, role, workspaceId, professionalTitle, bio, portfolioUrls, workingLanguage, timezone, notificationPreferences, createdAt.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-18</strong>: /users/me resolves identity from the JWT principal only, so a user can never read another user&#39;s profile.</li><li><strong>BR-94</strong>: role defaults to USER when no role record exists; workspaceId falls back to the user&#39;s first active workspace membership when the token carries none.</li><li><strong>BR-95</strong>: timezone and notificationPreferences have no dedicated columns; both live inside the JSON preferences field.</li><li><strong>BR-96</strong>: avatarUrl is empty when no avatar was ever uploaded; a default initials avatar is shown — not an error.</li><li><strong>BR-97</strong>: professionalTitle, bio, and workingLanguage are plain nullable columns; portfolioUrls is a JSON string deserialized to a list (unparsable or blank returns an empty list, never an error).</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Empty required fields → not applicable (no request body).</li><li>Missing, expired, or invalid access token → Display: <strong>MSG22</strong>.</li><li>User record no longer exists → Display: <strong>MSG38</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The signed-in user opens /profile.</li></ol></li><li><ol start="2"><li>The application requests the signed-in user&#39;s own profile.</li></ol></li><li><ol start="3"><li>The system resolves the caller&#39;s identity from the access token and loads the matching user record.</li></ol></li><li><ol start="4"><li>The system resolves the system role, applying the default when no role record exists.</li></ol></li><li><ol start="5"><li>The system resolves the current workspace, falling back to the first active workspace membership when needed.</li></ol></li><li><ol start="6"><li>The system derives timezone and notificationPreferences from the stored preferences data.</li></ol></li><li><ol start="7"><li>The system returns the complete profile field set.</li></ol></li><li><ol start="8"><li>The application renders the read-only profile card, showing a default initials avatar when none exists.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Missing, expired, or invalid access token, the system displays <strong>MSG22</strong>. 3.a2: The user signs in again at /login (3.2.2).</li><li>3.b1: The user record no longer exists, the system displays <strong>MSG38</strong>. 3.b2: The user is signed out and returned to /login.</li><li>8.a1: No avatar has ever been set, avatarUrl is empty. 8.a2: The application shows a default initials avatar.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The signed-in user&#39;s profile is displayed with the values currently stored in the system.</li><li>No data is changed; the operation is read-only.</li></ul><h4 id="_3-3-2-update-profile" tabindex="-1">3.3.2 Update Profile <a class="header-anchor" href="#_3-3-2-update-profile" aria-label="Permalink to &quot;3.3.2 Update Profile&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user saves edits to their profile fields on /profile, or selects a new avatar image in the avatar upload dialog.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any authenticated user (role USER); a user updates only their own profile.</li><li><strong>Purpose</strong>: Let the user keep their personal information accurate — display name, phone number, professional title, bio, portfolio links, working language, timezone, notification preferences — and refresh their avatar.</li><li><strong>Interface</strong>: The Profile screen at /profile in edit mode: editable full-name field, phone field, job-title field, working-language field, bio textarea, a repeatable portfolio-URL list, a timezone selector, and a Save button. Saving submits a full update (PUT semantics). The avatar is changed separately through the avatar upload dialog. Cancel restores every field (including all four listed above) to its last-saved value.</li><li><strong>Data Processing</strong>: The system loads the user record, writes the submitted full name, phone, professional title, bio, portfolio URLs, and working language directly onto the record, merges the submitted timezone and notification preferences into the stored preferences data (only submitted fields are overwritten), persists the record, and returns the updated profile. Avatar upload is handled independently: the file is validated, stored, the previous avatar file removed when one exists, and the new reference saved.</li><li>Known gap: notificationPreferences is wired end-to-end on the backend, but the Profile screen has no UI for it yet.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Profile Screen (/profile, edit mode):</p><ul><li>Center: full-name input (required), phone input, job-title input, working-language input, bio textarea, repeatable portfolio URL inputs (add/remove), timezone selector. Email and avatar are shown but not editable from this form.</li><li>Buttons: Save (primary); Cancel — discards changes and restores last-saved values.</li><li>Footer: none.</li></ul><p>Figure — Avatar Upload Dialog:</p><ul><li>Center: image file selector and preview.</li><li>Buttons: Upload — submits the image; Cancel — closes without changes.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: fullName; an image file for the avatar upload action.</li><li><strong>Input optional</strong>: phone, professionalTitle, bio, portfolioUrls, workingLanguage, timezone, notificationPreferences.</li><li><strong>System data</strong>: users (fullName, phone, professionalTitle, bio, portfolioUrls, workingLanguage, preferences JSON, avatarUrl).</li><li><strong>Output</strong>: userId, email, fullName, avatarUrl, phone, role, workspaceId, professionalTitle, bio, portfolioUrls, workingLanguage, timezone, notificationPreferences, createdAt; avatar upload returns the new avatarUrl.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-19</strong>: The update request carries no email or avatar field, so neither can be submitted through this action; changing email is out of scope.</li><li><strong>BR-98</strong>: Only fields actually submitted (non-empty) overwrite the stored preferences data.</li><li><strong>BR-20</strong>: Avatar upload — file required, content type must start with image/, max 5 MB.</li><li><strong>BR-99</strong>: When a new avatar uploads successfully, the previous avatar file is deleted.</li><li><strong>BR-100</strong>: Removing the avatar results in the default initials avatar, not an error.</li><li><strong>BR-101</strong>: Avatar upload is independent of the profile field update; one failing does not block the other.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>fullName empty or blank → Display: <strong>MSG02</strong>.</li><li>Preferences data cannot be serialized (rare) → Display: <strong>MSG02</strong>.</li><li>Avatar upload: no file provided → Display: <strong>MSG27</strong>; wrong content type → Display: <strong>MSG28</strong>; file exceeds 5 MB → Display: <strong>MSG29</strong>; file cannot be read → Display: <strong>MSG38</strong>.</li><li>Missing, expired, or invalid access token → Display: <strong>MSG22</strong>.</li><li>User record no longer exists → Display: <strong>MSG38</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The user edits the form on /profile and clicks Save.</li></ol></li><li><ol start="2"><li>The application submits the changed profile fields.</li></ol></li><li><ol start="3"><li>The system loads the user record and writes the submitted full name and phone number.</li></ol></li><li><ol start="4"><li>The system merges the submitted timezone and notification preferences into the stored preferences data, overwriting only submitted fields.</li></ol></li><li><ol start="5"><li>The system persists the record and returns the complete updated profile.</li></ol></li><li><ol start="6"><li>The application shows a success confirmation and refreshes the profile without a page reload; toast <strong>MSG26</strong>.</li></ol></li><li><ol start="7"><li>Separately, the user selects an image in the avatar upload dialog and submits it.</li></ol></li><li><ol start="8"><li>The system validates the file, stores it, deletes the previous avatar file when one exists, saves the new reference, and returns the new avatar value; toast <strong>MSG30</strong>.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: The user record no longer exists, the system displays <strong>MSG38</strong>. 3.a2: The user is signed out and returned to /login.</li><li>3.b1: fullName submitted empty or blank, the system displays <strong>MSG02</strong>. 3.b2: The user re-enters a full name and saves again.</li><li>4.a1: The preferences data cannot be serialized, the system displays <strong>MSG02</strong>. 4.a2: The user retries Save.</li><li>8.a1: No file is provided, the system displays <strong>MSG27</strong>. 8.a2: The user selects a file and submits again.</li><li>8.b1: The file&#39;s content type is not an image, the system displays <strong>MSG28</strong>. 8.b2: The user selects an image file and submits again.</li><li>8.c1: The file exceeds 5 MB, the system displays <strong>MSG29</strong>. 8.c2: The user selects a smaller image and submits again.</li><li>8.d1: The file cannot be read during upload, the system displays <strong>MSG38</strong>. 8.d2: The user retries the upload.</li><li>8.e1: The avatar is removed instead of replaced, the default initials avatar is shown, no error.</li><li>N.a1: Missing, expired, or invalid access token at any step, the system displays <strong>MSG22</strong>. N.a2: The user signs in again at /login (3.2.2).</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>fullName, phone, professionalTitle, bio, portfolioUrls, workingLanguage, timezone, and notificationPreferences hold the submitted values; fields left out keep their previous values.</li><li>The avatar reference reflects the most recent successful upload, or the default initials avatar when removed.</li><li>The avatar is stored independently of the profile field update.</li></ul><h4 id="_3-3-3-view-client-profile" tabindex="-1">3.3.3 View Client Profile <a class="header-anchor" href="#_3-3-3-view-client-profile" aria-label="Permalink to &quot;3.3.3 View Client Profile&quot;">​</a></h4><p>&gt; V2 (2026-10-02): ClientProfile reworked — owned by the User, independent of any Agency. See the full FR doc <code>profile/3-3-3-view-client-profile/spec.md</code> for details; this is a condensed copy kept in sync.</p><p><strong>Function Trigger</strong></p><p>Begins when a user opens their own list of Client Profiles (&quot;My Brand Profiles&quot;), or when an Agency Manager/Owner opens a workspace&#39;s Client list to manage collaborating clients.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any signed-in user, viewing the Client Profiles they personally own; Agency members (Owner/Manager) when viewing a workspace&#39;s Client list (<code>/workspaces/{id}/clients</code>).</li><li><strong>Purpose</strong>: Let a user manage the Client Profiles they own — one person may represent several brands (e.g. Nike, Adidas) and hold one profile per brand, none of which belong to any Agency. A profile is reused across every workspace/Agency the user collaborates with.</li><li><strong>Interface</strong>: The personal screen at /client-profiles lists every Client Profile the signed-in user owns — no Agency context required. A separate Workspace Client list, at /workspaces/{id}/clients, shows every WorkspaceMember with role CLIENT currently linked to that workspace (via client_profile_id).</li><li><strong>Data Processing</strong>: The system resolves the caller&#39;s identity from the access token and returns every Client Profile where userId matches the caller. For the workspace list, the system returns the workspace&#39;s active CLIENT members joined with their linked Client Profile for display.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — My Brand Profiles (/client-profiles):</p><ul><li>Center: list of every Client Profile the signed-in user owns — display name, company, contact details, logo.</li><li>Buttons: Create new profile, Edit, Delete (blocked if linked to an active workspace membership).</li></ul><p>Figure — Workspace Client List (/workspaces/{id}/clients):</p><ul><li>Center: list of active CLIENT members of this workspace — display name (from the linked Client Profile), joined date, status.</li><li>Buttons: &quot;Add client&quot; (Owner/Manager only) — opens an invite-by-email dialog (see 3.4.7 for the invite flow).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: None beyond the caller&#39;s identity (My Brand Profiles); the workspace identifier, for the Workspace Client list.</li><li><strong>Input optional</strong>: None.</li><li><strong>System data</strong>: client_profiles — id, userId, displayName, company, phone, note, logoUrl, website, industry, location, description, socialLinks, plus brand fields, createdAt, updatedAt. The link to a workspace is client_profile_id on workspace_members, not any field on client_profiles.</li><li><strong>Output</strong>: Every Client Profile owned by the caller, or the list of active CLIENT members for one workspace.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-41 (reworked)</strong>: A Client Profile belongs to exactly one User and is never scoped to an Agency. One user may hold several independent Client Profiles — one per brand/customer they represent — completely unrelated to how many Agencies or workspaces they collaborate with.</li><li><strong>BR-102</strong>: The same Client Profile can be linked to any number of workspaces across any number of Agencies simultaneously.</li><li><strong>BR-103</strong>: A Client Profile is created either explicitly by its owner, or inline during a CLIENT invitation accept flow — never implicitly, and never keyed by an Agency.</li><li><strong>BR-38</strong>: Client access is scoped by workspace membership — a client can only see/approve content in workspaces where their Client Profile is actively linked. A Client Profile is independent of the user&#39;s own User Profile (3.3.1).</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Missing, expired, or invalid access token → Display: <strong>MSG22</strong>.</li><li>Workspace Client list: missing or invalid workspace identifier → 404 WORKSPACE_NOT_FOUND.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The user opens &quot;My Brand Profiles&quot; (/client-profiles).</li></ol></li><li><ol start="2"><li>The system resolves the caller&#39;s identity from the access token.</li></ol></li><li><ol start="3"><li>The system returns every Client Profile where userId matches the caller.</li></ol></li><li><ol start="4"><li>The application renders the list — one card per brand the user represents.</li></ol></li><li><ol start="5"><li>Alternatively, an Agency Manager/Owner opens a workspace&#39;s Client list; the system returns that workspace&#39;s active CLIENT members, and the application displays them with an &quot;Add client&quot; action.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>N.a1: Missing, expired, or invalid access token at any step, the system displays <strong>MSG22</strong>. N.a2: The user signs in again at /login (3.2.2).</li><li>5.a1: Invalid or missing workspace identifier → 404 WORKSPACE_NOT_FOUND. 5.a2: The application returns to the workspace list.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Every Client Profile owned by the caller is displayed with the values currently stored for it, independent of any Agency context.</li><li>The Workspace Client list reflects the workspace&#39;s current active CLIENT members only.</li><li>No data is changed; the operation is read-only.</li></ul><h4 id="_3-3-4-update-client-profile" tabindex="-1">3.3.4 Update Client Profile <a class="header-anchor" href="#_3-3-4-update-client-profile" aria-label="Permalink to &quot;3.3.4 Update Client Profile&quot;">​</a></h4><p>&gt; V2 (2026-10-02): ClientProfile reworked — owned by the User, independent of any Agency. See the full FR doc <code>profile/3-3-4-update-client-profile/spec.md</code> for details; this is a condensed copy kept in sync.</p><p><strong>Function Trigger</strong></p><p>Begins when a user creates a new Client Profile or saves edits to one of their existing Client Profiles, on the &quot;My Brand Profiles&quot; screen (/client-profiles).</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any signed-in user, editing a Client Profile they own.</li><li><strong>Purpose</strong>: Let a user keep the brand information they represent up to date, or add a new brand profile. The email address cannot be set on a Client Profile — it is always the fixed identity of the owning user.</li><li><strong>Interface</strong>: The &quot;My Brand Profiles&quot; screen (3.3.3) in create/edit mode. Editable fields: display name (required), company, phone number, note, logo, website, industry, location, description, social links, plus brand fields. No email field for the owner&#39;s own identity, and no Agency selector anywhere in the form.</li><li><strong>Data Processing</strong>: The system resolves the caller&#39;s identity from the access token. For create, it inserts a new client_profiles row owned by the caller. For update, it looks up the profile by id, verifies userId matches the caller, writes the complete submitted field set over the record, stamps the update time, and persists. The record is never scoped to an Agency, so the update is visible wherever that profile is linked at once.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Brand Profile form (/client-profiles, create/edit):</p><ul><li>Center: display name input (required), company, phone number, note, logo, website, industry, location, description, social links, and brand-field inputs.</li><li>Buttons: Save (primary); Cancel; Delete (edit mode only, blocked while linked to an active workspace membership).</li><li>No email field is present in the form.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: displayName.</li><li><strong>Input optional</strong>: company, phone, note, logoUrl, website, industry, location, description, socialLinks, plus brand fields (contactName, contactEmail, companySize, instagramUrl, taxCode, address, tagline, foundedYear, budgetRange).</li><li><strong>System data</strong>: client_profiles — id, userId, displayName, company, phone, note, logoUrl, website, industry, location, description, socialLinks, plus the brand fields above, createdAt, updatedAt.</li><li><strong>Output</strong>: The complete Client Profile field set after the record is created or updated.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-104</strong>: Create and update are separate requests (POST / PUT by id), not an upsert keyed by any (user, agency) pair.</li><li><strong>BR-105</strong>: The update is a full overwrite, not a partial patch — fields left out are written as empty.</li><li><strong>BR-38 (reworked)</strong>: A Client Profile is never scoped to a single Agency — editing it updates the one record everywhere it is linked.</li><li><strong>BR-19</strong>: Email and role are not mutable via this action; the request carries no email field for the owner&#39;s own account.</li><li><strong>BR-106</strong>: displayName is mandatory and must not be blank.</li><li><strong>BR-107</strong>: A Client Profile cannot be deleted while linked to an active workspace membership — CLIENT_PROFILE_IN_USE.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>displayName empty or blank → Display: <strong>MSG02</strong>.</li><li>Update/delete on a profile not owned by the caller → 403 CLIENT_PROFILE_NOT_OWNED.</li><li>Delete while linked to an active workspace membership → 409 CLIENT_PROFILE_IN_USE.</li><li>Missing, expired, or invalid access token → Display: <strong>MSG22</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The user opens &quot;My Brand Profiles&quot;, fills the form, and clicks Save.</li></ol></li><li><ol start="2"><li>The application submits the complete set of Client Profile fields.</li></ol></li><li><ol start="3"><li>The system resolves the caller&#39;s identity from the access token.</li></ol></li><li><ol start="4"><li>For update, the system looks up the profile by id and verifies ownership.</li></ol></li><li><ol start="5"><li>The system writes the submitted fields over the record and stamps the update time.</li></ol></li><li><ol start="6"><li>The system persists the record and returns the complete Client Profile field set.</li></ol></li><li><ol start="7"><li>The application confirms success and refreshes the list; the new values appear everywhere the profile is linked at once.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: displayName submitted empty or blank, the system displays <strong>MSG02</strong>. 1.a2: The user re-enters a display name and saves again.</li><li>4.a1: The profile id belongs to a different user → 403 CLIENT_PROFILE_NOT_OWNED. 4.a2: The application shows an access-denied error.</li><li>7.a1: An email address is submitted for the owner&#39;s own identity, it cannot be carried by the request. 7.a2: The field is silently ignored.</li><li>Delete.a1: The profile is linked to an active workspace membership → 409 CLIENT_PROFILE_IN_USE. Delete.a2: The user removes it from every workspace first.</li><li>N.a1: Missing, expired, or invalid access token at any step, the system displays <strong>MSG22</strong>. N.a2: The user signs in again at /login (3.2.2).</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The Client Profile holds exactly the submitted field values; fields left out are empty (full overwrite, not a partial patch).</li><li>The updated values are visible wherever the profile is currently linked, across every Agency.</li><li>Other Client Profiles owned by the same or different users are unchanged.</li></ul><h4 id="_3-4-1-list-agency" tabindex="-1">3.4.1 List Agency <a class="header-anchor" href="#_3-4-1-list-agency" aria-label="Permalink to &quot;3.4.1 List Agency&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user navigates to the Agencies page (/agencies), the default landing page for a user who already owns or belongs to at least one Agency.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Agency Owner or Agency Member.</li><li><strong>Purpose</strong>: Show every Agency the current user owns or belongs to, so the user can pick one to manage.</li><li><strong>Interface</strong>: Agencies page — a grid of Agency cards showing name, logo and category, with an empty state and a &quot;Create new Agency&quot; call to action when the user has none.</li><li><strong>Data Processing</strong>: The system merges the Agencies the user owns with the Agencies where the user holds a Member record, de-duplicates, excludes soft-deleted Agencies, and returns the combined list with each Agency&#39;s full profile.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Agencies page:</p><ul><li>A card per Agency, showing name, logo and category.</li><li>Selecting a card moves the user into that Agency; the Agency Dashboard (3.4.2) has no screen yet, so the Agency Profile (3.4.4) is shown in the meantime.</li><li>Empty state with a &quot;Create new Agency&quot; call to action.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: none.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: Agency profile — id, name, ownerId, logoUrl, description, category, companySize, website, phone, location, brandColor, logoIcon, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, status (ACTIVE / SOFT_DELETED), createdAt, updatedAt.</li><li><strong>Output</strong>: list of Agencies matching the current user, each with the full profile; empty list when the user has none.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29</strong>: Multi-tenancy — list is scoped to Agencies the user owns or belongs to as a Member, whatever the role.</li><li><strong>BR-108</strong>: Soft-deleted Agencies are excluded from the list.</li><li><strong>BR-109</strong>: The result carries no pre-computed workspace count.</li><li><strong>BR-110</strong>: Selecting an Agency leads to the Agency Dashboard (3.4.2); the Agency Profile (3.4.4) stands in until that screen exists.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>None — the operation always returns a list, empty or not.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The user opens the Agencies page.</li></ol></li><li><ol start="2"><li>The client requests the Agency list of the signed-in user.</li></ol></li><li><ol start="3"><li>The system gathers owned and member Agencies, merges and de-duplicates, drops soft-deleted entries, and returns the result.</li></ol></li><li><ol start="4"><li>The client renders one card per Agency.</li></ol></li><li><ol start="5"><li>The user selects a card to move into that Agency.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: User owns and belongs to no Agency → an empty list is returned, no error. 3.a2: The client shows the empty state with the &quot;Create new Agency&quot; call to action.</li><li>2.a1: No signed-in session → 401 UNAUTHORIZED before any Agency logic runs.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The list reflects exactly the Agencies the current user owns or belongs to, soft-deleted ones excluded.</li><li>No Agency data is created, changed or removed.</li></ul><h4 id="_3-4-2-view-agency-dashboard" tabindex="-1">3.4.2 View Agency Dashboard <a class="header-anchor" href="#_3-4-2-view-agency-dashboard" aria-label="Permalink to &quot;3.4.2 View Agency Dashboard&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Proposed — not yet implemented. The intended trigger is the Owner opening the dashboard of one of their Agencies (/agencies/:agencyId/dashboard). No dashboard screen exists in the current system.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Agency Owner. Proposed — not yet implemented.</li><li><strong>Purpose</strong>: Give the Owner an overview of one Agency — Workspace count, Member count, Client count and recent activity.</li><li><strong>Interface</strong>: Agency Dashboard page (/agencies/:agencyId/dashboard) — proposed; not yet implemented.</li><li><strong>Data Processing</strong>: The system would count the Members, Workspaces and distinct Clients of the Agency and return them with a recent-activity list. Only the Member count can be derived from existing data today; the rest still needs design.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Agency Dashboard:</p><ul><li>Summary tiles for Workspace count, Member count and Client count.</li><li>A recent-activity list.</li><li>Proposed — not yet implemented; the layout is indicative only.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Agency identifier (agencyId).</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: Agency profile, the Agency Member records, the Workspaces of the Agency, and the Client Profile records of those Workspaces. Recent activity has no agreed data source yet.</li><li><strong>Output</strong>: proposed — a summary with Workspace count, Member count and Client count, plus recent activity. Not yet implemented.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29 (approximated)</strong>: only the Owner of the Agency may view its dashboard; anybody else is refused with 403 FORBIDDEN, mirroring the workspace-scoped access rule since no Agency-dashboard-specific BR exists yet.</li><li><strong>BR-111</strong>: The Agency must exist and must not be soft-deleted, otherwise 404 AGENCY_NOT_FOUND.</li><li><strong>BR-112</strong>: The Member count covers every Agency Member record of the Agency, whatever the role.</li><li><strong>BR-113</strong>: Proposed — not yet implemented: the Workspace and Client counts, and the recent-activity list, still have to be defined.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller is not the Agency Owner → Display: <strong>MSG39</strong></li><li>Agency does not exist or is soft-deleted → Display: <strong>MSG38</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The Owner opens the Agency Dashboard. (Proposed — not yet implemented.)</li></ol></li><li><ol start="2"><li>The client requests the dashboard summary for the Agency.</li></ol></li><li><ol start="3"><li>The system confirms the Agency exists and that the caller is its Owner.</li></ol></li><li><ol start="4"><li>The system counts Members, Workspaces and distinct Clients, and collects recent activity.</li></ol></li><li><ol start="5"><li>The system returns the summary and the client renders it.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Caller is not the Agency Owner → 403 FORBIDDEN, toast <strong>MSG39</strong>. 3.a2: The caller returns to the Agency list and opens an Agency they own.</li><li>3.b1: Agency does not exist or is soft-deleted → 404 AGENCY_NOT_FOUND, toast <strong>MSG38</strong>. 3.b2: The caller returns to the Agency list.</li><li>4.a1: Agency just created with no Workspace yet → every count returns zero, not an error, no toast. 4.a2: The Owner creates a Workspace to start populating the dashboard.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>No Agency data is created, changed or removed. (Proposed — not yet implemented.)</li></ul><h4 id="_3-4-3-create-agency" tabindex="-1">3.4.3 Create Agency <a class="header-anchor" href="#_3-4-3-create-agency" aria-label="Permalink to &quot;3.4.3 Create Agency&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>A signed-in user submits the Create Agency form, from the Agencies page (/agencies/create) or a dialog opened on that page.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Signed-in user, who becomes the Owner of the Agency being created.</li><li><strong>Purpose</strong>: Let a user open a new Agency on BrandHub and start running their communications company from it.</li><li><strong>Interface</strong>: Create Agency page or dialog — a form with a required name field and optional branding fields (logo, description, category, company size, website, phone, location, brand colour, logo icon, tagline, founded year, Facebook, LinkedIn, Instagram links).</li><li><strong>Data Processing</strong>: The system validates the form, stores a new Agency with the current user as Owner and status ACTIVE, and records the same user as an Agency Member at the OWNER role in the same operation. The logo is uploaded afterwards, once the Agency has an identifier.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Create Agency form:</p><ul><li>Name (required) and the optional branding fields listed above.</li><li>A logo picker: the file is uploaded after the Agency is created, not through the form itself.</li><li>A submit action; on success the user is taken into the newly created Agency.</li><li>The form is reachable from the Agencies page, where an empty state also offers the same call to action.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: name of the Agency.</li><li><strong>Input optional</strong>: logoUrl, description, category, companySize, website, phone, location, brandColor (hex, max 9 chars), logoIcon, tagline (max 140 chars), foundedYear, facebookUrl, linkedinUrl, instagramUrl.</li><li><strong>System data</strong>: the Agency record — id, name, ownerId, logoUrl, description, category, companySize, website, phone, location, brandColor, logoIcon, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, status, createdAt, updatedAt — and the Agency Member record pairing the Agency with its Owner at the OWNER role.</li><li><strong>Output</strong>: the profile of the newly created Agency, including its identifier, Owner and status ACTIVE. The logo upload returns the same profile with the logo filled in.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-24 (analogous)</strong>: creating an Agency inserts the creator as an Agency Member with role OWNER, mirroring the workspace-creation rule. Name is mandatory; an empty name is refused with 400 VALIDATION_ERROR.</li><li><strong>BR-114</strong>: Brand colour is limited to 9 characters and tagline to 140 characters; a longer value is refused with 400 VALIDATION_ERROR.</li><li><strong>BR-115</strong>: The creator becomes the Owner and an Agency Member record at OWNER role is created for the same user; the pairing is fixed and cannot be reassigned by any other feature in the current scope.</li><li><strong>BR-116</strong>: The logo is not part of the main form; it is uploaded as a file through the Agency logo upload once the Agency identifier exists. A logo URL may still be passed as text, but the standard journey uploads the file separately.</li><li><strong>BR-117</strong>: On success the user is taken into the newly created Agency.</li><li><strong>BR-118</strong>: A user may own any number of Agencies; no creation limit in the current scope.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Name empty → Display: <strong>MSG02</strong></li><li>Brand colour over 9 characters, or tagline over 140 characters → Display: <strong>MSG03</strong></li><li>No signed-in session → 401 UNAUTHORIZED before any Agency logic runs.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The user opens the Create Agency form and fills in the name and, optionally, the branding fields.</li></ol></li><li><ol start="2"><li>The client submits the form.</li></ol></li><li><ol start="3"><li>The system validates the values against the rules above.</li></ol></li><li><ol start="4"><li>The system stores a new Agency with the current user as its Owner and status ACTIVE.</li></ol></li><li><ol start="5"><li>The system stores an Agency Member record with the OWNER role for that same user.</li></ol></li><li><ol start="6"><li>The system returns the profile of the new Agency and the client moves the user into it; toast <strong>MSG31</strong>.</li></ol></li><li><ol start="7"><li>The user optionally uploads a logo file; the system stores the file, fills in the logo, and returns the updated profile; toast <strong>MSG94</strong>.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Name left empty → 400 VALIDATION_ERROR, Display: <strong>MSG02</strong>; nothing is created. 3.a2: The user fills in the name and resubmits.</li><li>3.b1: Brand colour or tagline over its limit → 400 VALIDATION_ERROR, Display: <strong>MSG03</strong>; nothing is created. 3.b2: The user shortens the field and resubmits.</li><li>1.a1: No signed-in session → 401 UNAUTHORIZED, toast <strong>MSG22</strong>. 1.a2: The user signs in again and retries.</li><li>7.a1: The logo file fails to be read → 400 FILE_READ_ERROR, toast <strong>MSG29</strong>; the Agency itself remains created. 7.a2: The user selects a valid file and retries the upload.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>A new Agency exists with the current user as its Owner and status ACTIVE.</li><li>An Agency Member record with the OWNER role exists for that user.</li><li>If a logo was uploaded, the Agency profile carries the logo URL and a refreshed update timestamp.</li></ul><h4 id="_3-4-4-view-agency-profile" tabindex="-1">3.4.4 View Agency Profile <a class="header-anchor" href="#_3-4-4-view-agency-profile" aria-label="Permalink to &quot;3.4.4 View Agency Profile&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>A signed-in user opens the profile of an Agency they belong to, as Owner or as a Member. The profile is also shown right after selecting an Agency from the Agency list (3.4.1).</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Agency Owner or Agency Member (any member role).</li><li><strong>Purpose</strong>: Show the branding and company information of an Agency to the people who work in it.</li><li><strong>Interface</strong>: Agency Profile page (/agencies/:agencyId/profile) — the branding section with name, logo, description, category, company size, contact details, brand colour, logo icon, tagline, founded year and social links. No separate profile data source; the page reads the same Agency profile used elsewhere.</li><li><strong>Data Processing</strong>: The system loads the Agency by its identifier, checks that the caller is the Owner or holds a Member record, and returns the branding and company information.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Agency Profile page:</p><ul><li>Header with name, logo, tagline and brand colour.</li><li>Company information: description, category, company size, website, phone, location, founded year (rendered as years in business).</li><li>Social links: Facebook, LinkedIn, Instagram.</li><li>No Workspace list and no Member list are shown here — company information only.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Agency identifier (agencyId) and a signed-in session.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: Agency profile — name, logoUrl, description, category, companySize, website, phone, location, brandColor, logoIcon, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, plus id, ownerId, status, createdAt, updatedAt. The caller&#39;s Agency Member records are used for the access check.</li><li><strong>Output</strong>: the profile of the Agency, restricted to branding and company information; no Workspace or Member data.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29 (analogous)</strong>: only the Owner, or a user holding a Member record, may view the profile. Any other signed-in user is refused with 400 NOT_AGENCY_MEMBER.</li><li><strong>BR-119</strong>: The Owner always has access, even with no Agency Member record; the Owner check stands on its own.</li><li><strong>BR-120</strong>: Every member role may view the profile — role does not narrow access.</li><li><strong>BR-121</strong>: The profile is not public; a user must be signed in and belong to the Agency.</li><li><strong>BR-122</strong>: This screen differs from the Agency Dashboard (3.4.2): profile carries branding and company information, dashboard carries management figures.</li><li><strong>BR-123</strong>: The profile response holds no internal detail beyond branding and company information.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>No signed-in session, or an invalid one → 401 UNAUTHORIZED, refused before Agency logic runs.</li><li>Agency does not exist → Display: <strong>MSG38</strong></li><li>Caller is neither the Owner nor a Member → Display: <strong>MSG39</strong></li><li>Agency already soft-deleted → the record is still returned, so Owner and Members can still view it. See 3.4.6 for removal behaviour.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The user opens the profile of an Agency.</li></ol></li><li><ol start="2"><li>The client requests the Agency profile with the signed-in session.</li></ol></li><li><ol start="3"><li>The system confirms the session, then loads the Agency by its identifier.</li></ol></li><li><ol start="4"><li>The system confirms the caller is the Owner or holds a Member record.</li></ol></li><li><ol start="5"><li>The system returns the branding and company information.</li></ol></li><li><ol start="6"><li>The client renders the profile, including years in business.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: No signed-in session, or an invalid one → 401 UNAUTHORIZED, toast <strong>MSG22</strong>. 2.a2: The user signs in again and retries.</li><li>3.a1: Agency does not exist → 404 AGENCY_NOT_FOUND, toast <strong>MSG38</strong>. 3.a2: The user returns to the Agency list.</li><li>4.a1: Caller belongs to no part of the Agency → 400 NOT_AGENCY_MEMBER, toast <strong>MSG39</strong>; no profile data returned. 4.a2: The user returns to the Agency list and opens an Agency they belong to.</li><li>4.b1: Agency already soft-deleted → the profile is still returned; no error, no toast. 4.b2: The user continues viewing normally.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>No Agency data is created, changed or removed.</li><li>The profile shows correct company information and exposes no internal information.</li></ul><h4 id="_3-4-5-update-agency-profile" tabindex="-1">3.4.5 Update Agency Profile <a class="header-anchor" href="#_3-4-5-update-agency-profile" aria-label="Permalink to &quot;3.4.5 Update Agency Profile&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>The Owner of an Agency opens the Agency Profile in edit mode (/agencies/:agencyId/profile/edit), changes one or more fields and submits the form, or uploads a new logo file while on that screen.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Agency Owner.</li><li><strong>Purpose</strong>: Let the Owner keep the Agency profile up to date — name, branding and company information.</li><li><strong>Interface</strong>: Edit Agency Profile page — the same field set as the Create Agency form, pre-filled with current values, plus a logo picker that uploads a new logo file.</li><li><strong>Data Processing</strong>: The system loads the Agency, confirms the caller is its Owner, validates the submitted values, then replaces the stored profile with the submitted values in full — every field not sent is cleared. The logo is uploaded separately and the system fills in the logo location.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Edit Agency Profile page:</p><ul><li>The full field set of the Agency profile, pre-filled from current values, name marked required.</li><li>A logo picker; the chosen file is uploaded separately from the form.</li><li>A save action; on success the user stays on the screen and sees the refreshed values.</li><li>Because save replaces the whole profile, every field that must survive has to be present when submitted.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: name of the Agency.</li><li><strong>Input optional</strong>: logoUrl, description, category, companySize, website, phone, location, brandColor (hex, max 9 chars), logoIcon, tagline (max 140 chars), foundedYear, facebookUrl, linkedinUrl, instagramUrl. The logo file itself goes through the separate logo upload.</li><li><strong>System data</strong>: the Agency record — id, name, ownerId, logoUrl, description, category, companySize, website, phone, location, brandColor, logoIcon, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, status, createdAt, updatedAt — and the Owner identifier used for the access check.</li><li><strong>Output</strong>: the updated profile. After a logo upload, the same profile with the new logo location and a refreshed update timestamp.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-25 (analogous)</strong>: updating the Agency profile is Owner-only, mirroring the rule that workspace settings can only be updated by an authorized role. Anybody else is refused with 403 NOT_AGENCY_OWNER.</li><li><strong>BR-124</strong>: The save replaces the whole profile rather than patching individual fields: a field not sent is cleared. The client must send back every current value, including unchanged ones.</li><li><strong>BR-125</strong>: Name is mandatory; an empty name is refused with 400 VALIDATION_ERROR.</li><li><strong>BR-126</strong>: The logo is uploaded as a file through the Agency logo upload, not through the logo URL field of the form.</li><li><strong>BR-127</strong>: A logo file that cannot be read is refused with 400 FILE_READ_ERROR; the stored profile stays untouched.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller is not the Agency Owner → Display: <strong>MSG39</strong></li><li>Name empty → Display: <strong>MSG02</strong></li><li>Agency does not exist → Display: <strong>MSG38</strong></li><li>Logo upload by a caller who is not the Agency Owner → Display: <strong>MSG39</strong></li><li>Logo file cannot be read → Display: <strong>MSG29</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The Owner opens the Agency Profile in edit mode; the form loads with current values.</li></ol></li><li><ol start="2"><li>The Owner changes the fields that need updating and leaves the rest as they are.</li></ol></li><li><ol start="3"><li>The client submits the full profile.</li></ol></li><li><ol start="4"><li>The system loads the Agency by its identifier and confirms the caller is its Owner.</li></ol></li><li><ol start="5"><li>The system validates the submitted values against the rules above.</li></ol></li><li><ol start="6"><li>The system replaces the stored profile with the submitted values and returns the updated profile; toast <strong>MSG26</strong>.</li></ol></li><li><ol start="7"><li>The Owner optionally picks a new logo file; the system stores the file, fills in the logo, and returns the updated profile; toast <strong>MSG94</strong>.</li></ol></li><li><ol start="8"><li>The client shows a confirmation and refreshes the form and logo preview.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>4.a1: Agency does not exist → 404 AGENCY_NOT_FOUND, toast <strong>MSG38</strong>. 4.a2: The Owner returns to the Agency list.</li><li>4.b1: Caller is not the Agency Owner → 403 NOT_AGENCY_OWNER, toast <strong>MSG39</strong>; nothing is changed. 4.b2: The caller returns to the Agency list.</li><li>5.a1: Name left empty → 400 VALIDATION_ERROR, Display: <strong>MSG02</strong>; nothing is changed. 5.a2: The Owner fills in the name and resubmits.</li><li>7.a1: Logo file cannot be read → 400 FILE_READ_ERROR, toast <strong>MSG29</strong>; the profile keeps its previous values. 7.a2: The Owner selects a valid file and retries.</li><li>3.a1: A field the form fails to send back is cleared, because save replaces the whole profile — expected behaviour, not an error. 3.a2: The Owner reviews the saved profile and resubmits any field found missing.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The profile carries the submitted values and a refreshed update timestamp.</li><li>After a logo upload, the profile carries the new logo location and a refreshed update timestamp.</li></ul><h4 id="_3-4-6-remove-agency" tabindex="-1">3.4.6 Remove Agency <a class="header-anchor" href="#_3-4-6-remove-agency" aria-label="Permalink to &quot;3.4.6 Remove Agency&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>The Owner of an Agency selects Remove in the Agency settings and confirms the removal dialog; or later selects Restore on an Agency removed within the last 30 days.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Agency Owner.</li><li><strong>Purpose</strong>: Let the Owner take an Agency out of use without losing it, so it can be restored within 30 days.</li><li><strong>Interface</strong>: Remove action in Agency settings, behind a two-step confirmation dialog that asks the Owner to type the Agency name and states the consequences, including that the Workspaces of the Agency are affected too. Restore is available on removed Agencies within the 30-day window. On the FE, a danger-zone section groups the Remove and Restore actions.</li><li><strong>Data Processing</strong>: The system loads the Agency, confirms the caller is its Owner, marks the Agency soft-deleted with a removal timestamp, and marks every Workspace of that Agency the same way with the same timestamp. Restoring marks the Agency active again, clears the removal timestamp, and does the same for the Workspaces removed in that same batch — Workspaces already removed on their own keep their removed state.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Remove Agency dialog:</p><ul><li>A two-step confirmation: the Owner types the Agency name to confirm.</li><li>The dialog lists the consequences, notably that the Workspaces of the Agency are removed along with it.</li><li>A danger-zone section in the Agency settings groups the Remove action and, for a removed Agency, the Restore action, available for 30 days after removal.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Agency identifier (agencyId) and a signed-in session as its Owner.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the status and removal timestamp of the Agency (ACTIVE / SOFT_DELETED) and the status and removal timestamp of every Workspace belonging to the Agency.</li><li><strong>Output</strong>: removal leaves no profile to show. Restore returns the Agency profile with status ACTIVE.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-26 (analogous)</strong>: delete Agency is Owner-only, mirroring the rule that delete Workspace is OWNER-only. Anybody else is refused with 403 NOT_AGENCY_OWNER.</li><li><strong>BR-128</strong>: Removal is soft: the Agency is marked SOFT_DELETED and stamped with the removal time. Nothing is erased, and the Agency can be restored.</li><li><strong>BR-129</strong>: Removal cascades to the Workspaces of the Agency: each is marked SOFT_DELETED with the same removal time as the Agency.</li><li><strong>BR-130</strong>: Restore is allowed only on an Agency currently SOFT_DELETED; otherwise 400 AGENCY_NOT_DELETED, Display: <strong>MSG101</strong>.</li><li><strong>BR-131</strong>: Restore is allowed only within 30 days of the removal timestamp; beyond that, 410 RESTORE_WINDOW_EXPIRED, Display: <strong>MSG102</strong>.</li><li><strong>BR-132</strong>: Restore marks the Agency ACTIVE with the removal timestamp cleared, and does the same for the Workspaces whose removal timestamp matches the removal batch exactly. A Workspace already removed on its own beforehand keeps its removed state.</li><li><strong>BR-133</strong>: When the 30-day window passes without a restore, the Agency may eventually be erased for good by a periodic clean-up, designed separately and not part of this feature today.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller is not the Agency Owner → Display: <strong>MSG39</strong></li><li>Agency does not exist → Display: <strong>MSG38</strong></li><li>Restore called on an Agency that was never removed → 400 AGENCY_NOT_DELETED, Display: <strong>MSG101</strong>.</li><li>Restore attempted more than 30 days after removal → 410 RESTORE_WINDOW_EXPIRED, Display: <strong>MSG102</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The Owner selects Remove in the Agency settings danger zone.</li></ol></li><li><ol start="2"><li>The confirmation dialog states the consequences and asks the Owner to type the Agency name.</li></ol></li><li><ol start="3"><li>The Owner confirms.</li></ol></li><li><ol start="4"><li>The system loads the Agency and confirms the caller is its Owner.</li></ol></li><li><ol start="5"><li>The system marks the Agency SOFT_DELETED with the current time.</li></ol></li><li><ol start="6"><li>The system marks every Workspace of the Agency SOFT_DELETED with the same removal time; toast <strong>MSG93</strong>.</li></ol></li><li><ol start="7"><li>The client shows a confirmation and takes the user back to the Agency list.</li></ol></li><li><ol start="8"><li>Within 30 days, the Owner selects Restore in the danger zone.</li></ol></li><li><ol start="9"><li>The system confirms the caller is the Owner, that the Agency is SOFT_DELETED, and that the removal happened less than 30 days ago.</li></ol></li><li><ol start="10"><li>The system marks the Agency ACTIVE with the removal timestamp cleared, and does the same for the Workspaces removed in that same batch.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>4.a1: Agency does not exist → 404 AGENCY_NOT_FOUND, toast <strong>MSG38</strong>. 4.a2: The Owner returns to the Agency list.</li><li>4.b1: Caller is not the Agency Owner → 403 NOT_AGENCY_OWNER, toast <strong>MSG39</strong>; nothing changes. 4.b2: The caller returns to the Agency list.</li><li>9.a1: Restore called on an Agency never removed → 400 AGENCY_NOT_DELETED, toast <strong>MSG101</strong>. 9.a2: The Owner reloads the Agency list, which shows it as already active.</li><li>9.b1: Restore attempted after the 30-day window → 410 RESTORE_WINDOW_EXPIRED, toast <strong>MSG102</strong>. 9.b2: The Owner accepts the Agency stays removed, or creates a new one.</li><li>10.a1: The Owner restores within 30 days after a mistaken removal → Workspaces removed in that same batch become ACTIVE again; no error. 10.a2: The Owner continues working in the restored Agency and its Workspaces.</li><li>10.b1: A Workspace had already been removed on its own beforehand → it is not brought back when the Agency is restored, since its removal timestamp differs from the removal batch; no error. 10.b2: The Owner restores that Workspace separately if still within its own window.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>After removal: the Agency and its Workspaces carry the SOFT_DELETED status and the same removal timestamp. Nothing is erased.</li><li>After a restore within the window: the Agency is ACTIVE with no removal timestamp, and Workspaces from the same removal batch are ACTIVE again, while Workspaces removed on their own stay removed.</li></ul><h4 id="_3-4-7-invite-agency-member" tabindex="-1">3.4.7 Invite Agency Member <a class="header-anchor" href="#_3-4-7-invite-agency-member" aria-label="Permalink to &quot;3.4.7 Invite Agency Member&quot;">​</a></h4><p>&gt; V2 (2026-10-02): inviting a CLIENT now also happens from the dedicated Workspace Client screen (/workspaces/:id/clients, FR 3.3.3), with an inline auto-suggest lookup (GET /agencies/{agencyId}/invite-lookup) and a mandatory Client Profile selection/creation step on accept. See the full FR doc <code>agency-workspace/3-4-7-invite-agency-member/spec.md</code> for details — condensed below unchanged except where noted.</p><p><strong>Function Trigger</strong></p><p>The Owner of an Agency opens the Member list of that Agency (/agencies/:agencyId/members) and submits the Invite Member form.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Agency Owner (sender) and the invited person, who may not have an account yet.</li><li><strong>Purpose</strong>: Let the Owner bring another person into the Agency by email invitation, optionally pre-assigning that person to one Workspace with a role.</li><li><strong>Interface</strong>: Member list page with an &quot;Invite member&quot; action - a form with a required email and optional invitee name, note, Workspace, role and expiry period. The invited person accepts through the link in the invitation email.</li><li><strong>Data Processing</strong>: The system confirms the caller is the Owner, checks the duplicate, pending-limit and Workspace rules, stores the invitation as PENDING with a unique token and expiry time, and sends the invitation email. Accepting the invitation later turns the invited person into a Member of the Agency, and adds them to the chosen Workspace when one was pre-assigned.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Invite Member form:</p><ul><li>Email (required), invitee name, note, Workspace selector, role selector and expiry period (1-30 days, 30 by default).</li><li>When role CLIENT is selected, a Workspace must also be selected before the form can be submitted.</li><li>On success a confirmation appears and the new PENDING invitation shows in the invitation table.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: email of the invited person.</li><li><strong>Input optional</strong>: inviteeName, note, workspaceId (mandatory when role = CLIENT), role (MANAGER, CREATOR, CLIENT), expiryDays (integer 1-30, 30 by default).</li><li><strong>System data</strong>: Agency Owner identifier, the Agency Member records (duplicate check), the PENDING invitations of the Agency (count and duplicate check), the invitation record - id, agencyId, agencyName, invitedEmail, invitedBy, token, note, workspaceId, workspaceName, role (nullable), status (PENDING, ACCEPTED, EXPIRED, REVOKED), expiresAt, acceptedAt (nullable), createdAt - and the Workspace record when one is pre-assigned.</li><li><strong>Output</strong>: the stored invitation, PENDING, carrying its token and expiry time; the invitation email sent. No in-app notification is produced.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-27</strong>: Invite is Owner-only; an already-active member cannot be re-invited; a second invite is blocked while a pending, unexpired invitation exists for the same email; invitation token is a random UUID with an expiry window. Anybody other than the Owner is refused with 403 NOT_AGENCY_OWNER.</li><li><strong>BR-134</strong>: The invited email must not already be a Member of the Agency; otherwise 409 ALREADY_AGENCY_MEMBER.</li><li><strong>BR-135</strong>: The invited email must not already hold a PENDING invitation for this Agency; otherwise 409 INVITATION_ALREADY_PENDING.</li><li><strong>BR-136</strong>: An Agency may hold at most 20 unexpired PENDING invitations; beyond that, 409 TOO_MANY_PENDING_INVITATIONS.</li><li><strong>BR-137</strong>: A Workspace sent with the invitation must belong to the same Agency; otherwise 400 WORKSPACE_NOT_IN_AGENCY.</li><li><strong>BR-138</strong>: With role MANAGER, the chosen Workspace must not already have an active manager, since a Workspace holds one manager only; otherwise 409 MANAGER_ALREADY_ASSIGNED.</li><li><strong>BR-139</strong>: With role CLIENT, a Workspace is mandatory from the moment of invitation; otherwise 400 WORKSPACE_REQUIRED_FOR_CLIENT_INVITE. A Client does not become an Agency Member and needs a Workspace so a Client Profile and a Workspace membership can be assigned on acceptance.</li><li><strong>BR-140</strong>: The expiry period is settable between 1 and 30 days and defaults to 30 days; a value outside that range is clamped back inside it.</li><li><strong>BR-141</strong>: The BA document states a fixed 3-day expiry with no configurability; the code implements 1-30 days, default 30. This spec follows the code&#39;s current behaviour - the two figures are not reconciled.</li><li><strong>BR-142</strong>: The invitation reaches the invited person by email only; no in-app notification is produced.</li><li><strong>BR-143</strong>: On acceptance, an invited person with no role or a role other than CLIENT becomes an Agency Member at the MEMBER role - the Agency level knows only OWNER and MEMBER. When the invitation carried a Workspace and a role of MANAGER or CREATOR, the matching Workspace membership is created at the same time.</li><li><strong>BR-144</strong>: There is no automatic acceptance when somebody registers with the invited email address; the invited person must open the link, or accept with the token, themselves.</li><li><strong>BR-145</strong>: CLIENT is included in the assignable roles for an invitation alongside MANAGER and CREATOR.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Email empty or malformed -&gt; Display: <strong>MSG02</strong> / <strong>MSG04</strong></li><li>Caller is not the Agency Owner -&gt; Display: <strong>MSG39</strong></li><li>Email already a Member of the Agency -&gt; Display: <strong>MSG34</strong></li><li>Email already holds a PENDING invitation for this Agency -&gt; Display: <strong>MSG35</strong></li><li>Agency already holds 20 PENDING invitations -&gt; Display: <strong>MSG97</strong></li><li>Workspace does not exist -&gt; Display: <strong>MSG38</strong></li><li>Workspace does not belong to this Agency -&gt; Display: <strong>MSG98</strong></li><li>Role MANAGER but the Workspace already has an active manager -&gt; Display: <strong>MSG95</strong></li><li>Role CLIENT without a Workspace -&gt; Display: <strong>MSG02</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The Owner opens the Member list of an Agency and fills in the Invite Member form.</li></ol></li><li><ol start="2"><li>The client submits the invitation.</li></ol></li><li><ol start="3"><li>The system confirms the caller is the Owner of the Agency.</li></ol></li><li><ol start="4"><li>The system rejects the invitation if the email already belongs to a Member, already holds a PENDING invitation, or the Agency has reached 20 PENDING invitations.</li></ol></li><li><ol start="5"><li>When a Workspace is sent, the system confirms it belongs to the Agency and, for role MANAGER, that it holds no active manager; for role CLIENT, the system confirms a Workspace was sent.</li></ol></li><li><ol start="6"><li>The system stores the invitation as PENDING with a unique token and the computed expiry time.</li></ol></li><li><ol start="7"><li>The system sends the invitation email with an accept link carrying the token, without holding up the answer to the client.</li></ol></li><li><ol start="8"><li>The system returns the stored invitation and the client shows a confirmation and adds the row to the PENDING table; toast <strong>MSG33</strong>.</li></ol></li><li><ol start="9"><li>The invited person opens the accept link; if they have no account yet, they register and sign in first - the invitation is never accepted automatically.</li></ol></li><li><ol start="10"><li>The system confirms the token, the PENDING status, the unexpired expiry time and that the signed-in email matches the invited email, then records the person as an Agency Member at the MEMBER role, and adds the matching Workspace membership when the invitation carried a Workspace and a role of MANAGER or CREATOR.</li></ol></li><li><ol start="11"><li>The system marks the invitation ACCEPTED with the acceptance time and adds the person to the Agency.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Caller is not the Agency Owner -&gt; 403 NOT_AGENCY_OWNER, toast <strong>MSG39</strong>; no invitation is stored. 3.a2: The caller returns to the Agency list and opens an Agency they own.</li><li>4.a1: Email already a Member of the Agency -&gt; 409 ALREADY_AGENCY_MEMBER, toast <strong>MSG34</strong>. 4.a2: The Owner picks a different email or reviews the existing member.</li><li>4.b1: Email already holds a PENDING invitation for this Agency -&gt; 409 INVITATION_ALREADY_PENDING, toast <strong>MSG35</strong>. 4.b2: The Owner waits for it to resolve or cancels it (3.4.8) before re-inviting.</li><li>4.c1: Agency already holds 20 PENDING invitations -&gt; 409 TOO_MANY_PENDING_INVITATIONS, toast <strong>MSG97</strong>. 4.c2: The Owner cancels stale invitations to free a slot, then resubmits.</li><li>5.a1: Workspace sent does not belong to this Agency -&gt; 400 WORKSPACE_NOT_IN_AGENCY, toast <strong>MSG98</strong>. 5.a2: The Owner selects a Workspace that belongs to this Agency.</li><li>5.b1: Role MANAGER but the Workspace already has an active manager -&gt; 409 MANAGER_ALREADY_ASSIGNED, toast <strong>MSG95</strong>. 5.b2: The Owner chooses a different Workspace or role.</li><li>5.c1: Role CLIENT without a Workspace -&gt; 400 WORKSPACE_REQUIRED_FOR_CLIENT_INVITE, Display: <strong>MSG02</strong>. 5.c2: The Owner selects a Workspace before submitting.</li><li>9.a1: The invited email has no account yet -&gt; the invitation is still sent, no error. 9.a2: The person must register, sign in and accept the invitation themselves.</li><li>10.a1: The invitation expires before it is accepted -&gt; 400 INVALID_INVITATION on acceptance, toast <strong>MSG100</strong>; no Agency membership is created. 10.a2: The invited person asks the Owner to send a new invitation.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>A PENDING invitation exists for the Agency, carrying its token, expiry time and any pre-assigned Workspace and role, and the invitation email has been sent.</li><li>After acceptance: an Agency Member record at the MEMBER role exists for the invited person, and the invitation is ACCEPTED with its acceptance time; when the invitation carried a Workspace with role MANAGER or CREATOR, the matching Workspace membership also exists.</li><li>No in-app notification is produced at any point.</li></ul><h4 id="_3-4-8-view-agency-invitation-status" tabindex="-1">3.4.8 View Agency Invitation Status <a class="header-anchor" href="#_3-4-8-view-agency-invitation-status" aria-label="Permalink to &quot;3.4.8 View Agency Invitation Status&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>An Owner opens the pending-invitation tab of an Agency to review, cancel or follow up its invitations; or an invited person opens their own pending invitations to see what is still open and to accept or decline.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Agency Owner (invitations of their Agency) and invited person (their own invitations).</li><li><strong>Purpose</strong>: Let both sides see where an invitation stands, so they know whether it is still open, has lapsed, has been accepted or has been withdrawn.</li><li><strong>Interface</strong>: For the Owner, a pending-invitation tab in the Member list (/agencies/:agencyId/members), listing every invitation with its status and a cancel action on the open ones. For the invited person, a &quot;My invitations&quot; section listing the invitations still valid, each with an accept and a decline action.</li><li><strong>Data Processing</strong>: The system returns the invitations of an Agency for its Owner, deriving the lapsed ones at read time, and returns the still-valid invitations addressed to the signed-in email for an invited person. Cancelling an open invitation withdraws it, and declining does the same from the invited person&#39;s side.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Invitation list:</p><ul><li>Owner view: one row per invitation with the invited email, the pre-assigned Workspace and role if any, the expiry time, the derived status and a cancel action on the open ones.</li><li>Invited person view: one row per still-valid invitation with the Agency name, the expiry time, an accept action and a decline action.</li><li>Statuses shown as badges: PENDING, EXPIRED, ACCEPTED, REVOKED.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: for the Owner view, the Agency identifier (agencyId); for the invited-person view, the signed-in session. Cancelling needs the invitation identifier; declining needs the invitation token.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the invitations of the Agency - id, agencyId, agencyName, invitedEmail, invitedBy, token, note, workspaceId, workspaceName, role (nullable), status (PENDING, ACCEPTED, EXPIRED, REVOKED), expiresAt, acceptedAt (nullable), createdAt - and the email of the signed-in user.</li><li><strong>Output</strong>: for the Owner, every invitation of the Agency whatever its status, lapsed ones shown as expired. For the invited person, only the invitations addressed to their email that are still open. Cancelling and declining return no data.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-27</strong>: Only the Owner of the Agency may list or cancel its invitations, per the same Invite rule adapted to the Agency&#39;s single-Owner model. Anybody else is refused with 403 NOT_AGENCY_OWNER.</li><li><strong>BR-146</strong>: An invitation is valid for the period set when it was sent - 30 days by default, settable between 1 and 30 days.</li><li><strong>BR-147</strong>: The same BA/code conflict noted in 3.4.7 applies here: the BA document states a fixed 3-day expiry, the code implements 1-30 days, default 30. Not yet reconciled.</li><li><strong>BR-148</strong>: Expiry is derived when the list is read, not by a scheduled job: after the expiry time passes the stored record keeps its PENDING status, and the system reports it as EXPIRED without writing that back to storage. Two reads taken either side of the expiry time may report different statuses for the same record.</li><li><strong>BR-149</strong>: The Owner sees lapsed invitations reported as expired. The invited person does not: their list drops anything that is no longer PENDING or has passed its expiry time.</li><li><strong>BR-150</strong>: The Owner may cancel an invitation while it is still PENDING, which moves it to REVOKED. An invitation already accepted, lapsed or withdrawn cannot be cancelled.</li><li><strong>BR-151</strong>: The invited person may decline an invitation with its token, which also moves it to REVOKED - the status model has no separate value for a declined invitation.</li><li><strong>BR-152</strong>: There is no renewal or resend of an existing invitation; sending a new invitation is the way forward, and the old one can only be withdrawn.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller is not the Agency Owner -&gt; Display: <strong>MSG39</strong></li><li>The invitation does not exist, or does not belong to the Agency -&gt; Display: <strong>MSG38</strong></li><li>Cancelling an invitation that is no longer PENDING -&gt; Display: <strong>MSG100</strong></li><li>Accepting an invitation that is not PENDING or has passed its expiry time -&gt; Display: <strong>MSG100</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The Owner opens the pending-invitation tab of an Agency.</li></ol></li><li><ol start="2"><li>The client requests the invitations of the Agency with the signed-in session.</li></ol></li><li><ol start="3"><li>The system confirms the caller is the Owner of the Agency.</li></ol></li><li><ol start="4"><li>The system reads every invitation of the Agency and reports the lapsed ones as EXPIRED at read time, without writing the change back.</li></ol></li><li><ol start="5"><li>The client renders the list with the reported statuses.</li></ol></li><li><ol start="6"><li>The invited person opens their own invitation list.</li></ol></li><li><ol start="7"><li>The system returns the invitations addressed to the signed-in email that are still PENDING and unexpired.</li></ol></li><li><ol start="8"><li>The client renders them with an accept and a decline action on each.</li></ol></li><li><ol start="9"><li>When the Owner selects cancel on an open invitation, the system moves it to REVOKED and the client drops the row; toast <strong>MSG103</strong>.</li></ol></li><li><ol start="10"><li>When the invited person selects decline, the system moves the invitation to REVOKED and the client drops the row.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Caller is not the Agency Owner -&gt; 403 NOT_AGENCY_OWNER, toast <strong>MSG39</strong>; no list is returned. 3.a2: The caller returns to the Agency list and opens an Agency they own.</li><li>9.a1: Cancelling an invitation that does not exist or belongs to another Agency -&gt; 404 INVITATION_NOT_FOUND, toast <strong>MSG38</strong>. 9.a2: The Owner refreshes the invitation list.</li><li>9.b1: Cancelling an invitation that has already been accepted, lapsed or withdrawn -&gt; 400 INVALID_INVITATION, toast <strong>MSG100</strong>. 9.b2: The Owner refreshes the list to see its current status.</li><li>10.a1: The invitation lapses exactly as the invited person accepts it -&gt; the system re-checks the PENDING status and the expiry time at acceptance and refuses with 400 INVALID_INVITATION, toast <strong>MSG100</strong>; no Agency membership is created. 10.a2: The invited person asks the Owner to send a new invitation.</li><li>4.a1: Because expiry is derived at read time, two reads taken either side of the expiry time may report different statuses for the same stored record - expected behaviour, not an error, no toast. 4.a2: The user re-reads the list if the status looks stale.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The Owner sees every invitation of the Agency with its current status, lapsed ones included.</li><li>The invited person sees only the invitations that are still valid for their email.</li><li>After a cancel or a decline, the invitation carries the REVOKED status.</li><li>No Agency membership is created while an invitation is not accepted.</li></ul><h4 id="_3-4-9-remove-member" tabindex="-1">3.4.9 Remove Member <a class="header-anchor" href="#_3-4-9-remove-member" aria-label="Permalink to &quot;3.4.9 Remove Member&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>The Owner of an Agency opens the Member list of that Agency (/agencies/:agencyId/members), selects Remove on a member row and confirms.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Agency Owner.</li><li><strong>Purpose</strong>: Let the Owner take a member out of the Agency so that person loses access, while everything they produced while working there stays with the Agency as shared property.</li><li><strong>Interface</strong>: Member list page with a Remove action on each member row and a confirmation step.</li><li><strong>Data Processing</strong>: The system loads the Agency, confirms the caller is its Owner, locates the member record inside that Agency, refuses the removal when the record is the Owner, and otherwise removes the member record. Removing the record ends the person&#39;s access to every Workspace of the Agency at once, while the resources they created remain in place, owned by the Agency as before.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Member list:</p><ul><li>One row per member with their name, email and member role.</li><li>A Remove action on each row behind a confirmation step, not offered for the Owner row.</li><li>On success the row disappears and the list refreshes.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Agency identifier (agencyId), the member record identifier (memberId) and a signed-in session as the Agency Owner.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the Agency record and its Owner identifier (access check), and the member record with its Agency and its role.</li><li><strong>Output</strong>: no data is returned. The member record is removed and the person loses access to the Agency and to all of its Workspaces.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-28</strong>: Remove member is Owner-only; the last remaining OWNER cannot be removed. Anybody other than the Owner is refused with 403 NOT_AGENCY_OWNER.</li><li><strong>BR-153</strong>: The identifier used is the member record of the Agency, not the person&#39;s user identifier. A record that does not exist, or belongs to another Agency, is refused with 404 NOT_FOUND.</li><li><strong>BR-154</strong>: The Owner&#39;s own member record can never be removed, whatever the caller attempts. The attempt is refused with 409 CANNOT_REMOVE_OWNER. There is no ownership transfer, so the Owner cannot hand the Agency over before stepping away.</li><li><strong>BR-155</strong>: Removing a member ends their access to every Workspace of the Agency at once, including Workspaces where they held a manager or member role, because access everywhere rests on the member record that has just been removed.</li><li><strong>BR-156</strong>: The resources the removed member created - tasks, materials, content and the like - are not removed and do not change owner. They stay with the Workspace and the Agency as shared property.</li><li><strong>BR-157</strong>: When the person is invited back into the Agency later, they can edit and continue using the resources they created before, because that work never stopped belonging to the Agency.</li><li><strong>BR-158</strong>: Work assigned to the removed member is not reassigned automatically. A manager has to handle it by hand.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller is not the Agency Owner -&gt; Display: <strong>MSG39</strong></li><li>The member record does not exist, or belongs to another Agency -&gt; Display: <strong>MSG38</strong></li><li>The member record is the Owner&#39;s own -&gt; Display: <strong>MSG37</strong>, and nothing is removed.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>The Owner opens the Member list of an Agency.</li></ol></li><li><ol start="2"><li>The Owner selects Remove on a member row other than their own and confirms.</li></ol></li><li><ol start="3"><li>The client submits the removal with the member record identifier.</li></ol></li><li><ol start="4"><li>The system loads the Agency and confirms the caller is its Owner.</li></ol></li><li><ol start="5"><li>The system locates the member record inside that Agency.</li></ol></li><li><ol start="6"><li>The system removes the member record.</li></ol></li><li><ol start="7"><li>The client drops the row and shows a confirmation; toast <strong>MSG36</strong>. The person loses access to the Agency and to every one of its Workspaces immediately.</li></ol></li><li><ol start="8"><li>The resources that person created stay in the Workspace and the Agency, unchanged and still usable.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>4.a1: Caller is not the Agency Owner -&gt; 403 NOT_AGENCY_OWNER, toast <strong>MSG39</strong>; nothing is removed. 4.a2: The caller returns to the Agency list and opens an Agency they own.</li><li>5.a1: The member record does not exist, or belongs to another Agency -&gt; 404 NOT_FOUND, toast <strong>MSG38</strong>. 5.a2: The Owner refreshes the Member list.</li><li>5.b1: Remove selected on the Owner&#39;s own row -&gt; 409 CANNOT_REMOVE_OWNER, toast <strong>MSG37</strong>; nothing is removed. 5.b2: The Owner accepts that self-removal is not available and, if stepping away, contacts support since there is no ownership transfer.</li><li>6.a1: The removed member had work in progress assigned to them in a Workspace -&gt; the work is not unassigned automatically; no error, no toast. 6.a2: A manager handles the reassignment by hand, because that work still belongs to the Workspace.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The member record no longer exists, and the person loses access to the Agency and to all of its Workspaces immediately.</li><li>The resources the person created remain with the Workspace and the Agency, and stay usable by anyone holding access.</li><li>Work assigned to the person remains assigned until a manager handles it.</li></ul><h4 id="_3-4-10-list-workspace" tabindex="-1">3.4.10 List Workspace <a class="header-anchor" href="#_3-4-10-list-workspace" aria-label="Permalink to &quot;3.4.10 List Workspace&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user opens the Workspace list screen.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any Workspace member (MANAGER, CREATOR, or CLIENT).</li><li><strong>Purpose</strong>: Shows every Workspace the current user belongs to, so the user can pick one to work in.</li><li><strong>Interface</strong>: Workspace list screen of the current user - a list of Workspace entries, not scoped under an Agency route.</li><li><strong>Data Processing</strong>: The system reads the current user&#39;s active Workspace memberships, loads the Workspace records those memberships point to, and maps each one to a Workspace summary.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Workspace List Screen:</p><ul><li>A single grid screen titled with the user&#39;s Workspaces.</li><li>Each card shows an initials badge, the Workspace name, and its slug; clicking a card opens the Workspace settings screen.</li><li>An empty state message is shown when the user belongs to no Workspace.</li><li>A &quot;Create Workspace&quot; button navigates to the create form (FR 3.4.12).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the caller&#39;s authenticated identity.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: active Workspace membership rows of the current user; the Workspace records those memberships reference.</li><li><strong>Output</strong>: the Workspaces the user belongs to - id, name, agencyId, slug, ownerId, settings, industry, companySize, website, phone, location, description, branding fields, social links, isActive, createdAt. The list card only renders name and slug.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29</strong>: A Workspace is returned when either the current user has an active membership in it (MANAGER, CREATOR, CLIENT), or the current user is the Owner of the Agency that Workspace belongs to.</li><li><strong>BR-03</strong>: The listing is read-only; the only failure is a missing session, rejected with 401.</li><li><strong>BR-159</strong>: Known gap: soft-deleted Workspaces are not excluded from this list - the query has no status filter, so a deleted Workspace may still appear until fixed.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller must be signed in -&gt; otherwise 401.</li><li>A user with no Workspace membership receives an empty list, not an error.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>User opens the Workspace list screen.</li></ol></li><li><ol start="2"><li>System reads the current user&#39;s active Workspace memberships.</li></ol></li><li><ol start="3"><li>System loads the Workspace records referenced by those memberships.</li></ol></li><li><ol start="4"><li>System maps each Workspace to a Workspace summary.</li></ol></li><li><ol start="5"><li>Screen shows the Workspaces the user belongs to; an empty list is shown when the user belongs to none.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>5.a1: User belongs to no Workspace -&gt; empty list, HTTP 200. 5.a2: The empty state is displayed.</li><li>5.b1: User is not signed in -&gt; 401. 5.b2: The user is redirected to sign in.</li><li>5.c1: A soft-deleted Workspace is still referenced by an owned Agency or membership (known gap) -&gt; it is still returned and displayed as active. 5.c2: No client workaround; tracked as a backend fix.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>No data is changed; the Workspaces the user belongs to are displayed.</li></ul><h4 id="_3-4-11-view-workspace-dashboard" tabindex="-1">3.4.11 View Workspace Dashboard <a class="header-anchor" href="#_3-4-11-view-workspace-dashboard" aria-label="Permalink to &quot;3.4.11 View Workspace Dashboard&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a Workspace member opens the Dashboard of a Workspace.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Workspace members with role MANAGER, CREATOR, or CLIENT.</li><li><strong>Purpose</strong>: Gives members an overview of the Workspace&#39;s members, campaigns, package negotiation status, and the parent Agency&#39;s AI credit usage.</li><li><strong>Interface</strong>: Workspace dashboard screen, showing summary cards.</li><li><strong>Data Processing</strong>: The system resolves the Workspace, confirms the caller is an active member, then aggregates active member count and role breakdown, campaign count and status breakdown, the current package negotiation status, and the parent Agency&#39;s AI credit usage for the current calendar month.</li><li>No Task or Material entity exists in this codebase, so the dashboard does not show a Task summary. AI credit usage is Agency-wide, not per-Workspace, and is labeled as Agency-scoped.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Workspace Dashboard Screen:</p><ul><li>Header carrying the Workspace name.</li><li>Four stat cards in a row: Active members, Total campaigns, Package status (or &quot;No package&quot;), Agency AI credits used this month.</li><li>Two breakdown cards: Members by role, Campaigns by status - each an empty list if the Workspace has none yet.</li><li>A newly created Workspace with no package/campaign shows member counts as normal, campaign count as 0, package status as &quot;No package&quot;.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: active WorkspaceMember rows; the Workspace&#39;s WorkspaceMediaPackage (if any) and its MediaCampaign rows; the parent Agency&#39;s AiCreditLedger row for the current month.</li><li><strong>Output</strong>: the full Workspace profile, active member count and role breakdown, campaign count and status breakdown, package negotiation status (nullable), the Agency id, the current month string, and the Agency&#39;s AI credits used this month.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29</strong>: Only members holding an active membership row in the Workspace may view its dashboard, enforced both at the controller and inside the service. There is no Workspace-level OWNER - OWNER exists only at Agency level.</li><li><strong>BR-03</strong>: The dashboard is read-only and changes no data.</li><li><strong>BR-04</strong>: An empty Workspace (no package, no campaigns) renders member counts normally and campaign/package fields as empty/zero/null rather than failing.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller must be an active member of the Workspace; otherwise 403 WORKSPACE_ACCESS_DENIED or 403 FORBIDDEN.</li><li>Workspace must exist; otherwise 404 WORKSPACE_NOT_FOUND.</li><li>A Workspace with no package/campaigns must render without error.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>Member opens the Dashboard of a Workspace.</li></ol></li><li><ol start="2"><li>System resolves the Workspace and confirms active membership (BR-29).</li></ol></li><li><ol start="3"><li>System aggregates active member count/role breakdown, campaign count/status breakdown, package negotiation status, and the Agency&#39;s current-month AI credit usage.</li></ol></li><li><ol start="4"><li>Screen renders the stat cards and breakdown lists; an empty Workspace shows zeros/empty lists without error.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: The Workspace does not exist -&gt; 404 WORKSPACE_NOT_FOUND, toast <strong>MSG38</strong>. 2.a2: The member returns to the Workspace list.</li><li>2.b1: Caller is not an active member of the Workspace -&gt; 403 WORKSPACE_ACCESS_DENIED or FORBIDDEN, toast <strong>MSG40</strong>. 2.b2: The member returns to the Workspace list.</li><li>3.a1: Workspace has no package yet -&gt; packageNegotiationStatus is null, totalCampaigns is 0. 3.a2: The member continues viewing the dashboard normally.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>No data is changed; the Workspace&#39;s member, campaign, package, and Agency AI credit summary is displayed.</li></ul><h4 id="_3-4-12-create-workspace" tabindex="-1">3.4.12 Create Workspace <a class="header-anchor" href="#_3-4-12-create-workspace" aria-label="Permalink to &quot;3.4.12 Create Workspace&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when the Agency Owner submits the Create Workspace form with a Workspace name and the target Agency.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: The Agency OWNER only.</li><li><strong>Purpose</strong>: Creates a Workspace inside an Agency; the creator becomes its MANAGER by default, and members may optionally be assigned - including transferring the MANAGER role - at creation time.</li><li><strong>Interface</strong>: Create Workspace form - name input, Agency field, extended Workspace profile fields, and an optional member-assignment block.</li><li><strong>Data Processing</strong>: The system validates the request, creates the Workspace row, inserts the creator&#39;s membership in the same transaction, then applies any assignment entries - demoting the creator to CREATOR when the MANAGER role was transferred.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Create Workspace Screen:</p><ul><li>A single form screen scoped to one Agency.</li><li>Name input (required) and the target Agency (required).</li><li>Optional extended fields: industry, company size, website, phone, location, description, brand colour, logo icon, tagline, founded year, social links.</li><li>Optional member-assignment block letting the user pick Agency members and a role each (MANAGER / CREATOR / CLIENT).</li><li>A &quot;Create&quot; action; on success the user is taken into the new Workspace.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: name; agencyId.</li><li><strong>Input optional</strong>: industry, companySize, website, phone, location, description, brandColor, logoIcon, tagline, foundedYear, social links, assignMembers (list of {userId, role}).</li><li><strong>System data</strong>: the caller&#39;s authenticated identity; the Agency membership of the caller; default Workspace settings; the created Workspace identifier.</li><li><strong>Output</strong>: the created Workspace - id, name, agencyId, settings, industry, companySize, website, phone, location, description, branding fields, social links, createdAt.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-24</strong>: Creating a workspace inserts the creator as a workspace_members row with role MANAGER (or CREATOR when the MANAGER role is transferred via assignMembers), isActive=true.</li><li><strong>BR-160</strong>: If assignMembers names exactly one other user as MANAGER, the creator is automatically demoted to CREATOR - a Workspace has exactly one active MANAGER at any time.</li><li><strong>BR-161</strong>: The Workspace row and the creator&#39;s membership row are created in a single transaction; assignMembers entries are applied immediately afterwards.</li><li><strong>BR-162</strong>: name empty or agencyId missing -&gt; 400 VALIDATION_ERROR.</li><li><strong>BR-163</strong>: More than one MANAGER entry in assignMembers besides the creator -&gt; 409 MANAGER_ALREADY_ASSIGNED.</li><li><strong>BR-29</strong>: The caller must be an active member of the target Agency and must specifically hold the OWNER role, checked before the Workspace row is built; otherwise 403 NOT_AGENCY_OWNER.</li><li><strong>BR-164</strong>: An assignMembers entry whose user is not a member of that Agency -&gt; 403 NOT_AGENCY_MEMBER.</li><li><strong>BR-165</strong>: An assignMembers entry whose user record does not exist -&gt; USER_NOT_FOUND.</li><li><strong>BR-166</strong>: An assignMembers entry whose user already has an active membership in the new Workspace is skipped without error.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>name empty -&gt; Display: <strong>MSG02</strong>.</li><li>agencyId missing -&gt; 400 VALIDATION_ERROR, Display: <strong>MSG02</strong>.</li><li>industry must be a valid WorkspaceIndustry value; companySize must be a valid CompanySize value.</li><li>foundedYear, when supplied, must be a numeric year.</li><li>Every assignMembers role must be one of MANAGER / CREATOR / CLIENT - there is no workspace-level OWNER, OWNER exists only at Agency level.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>User opens the Create Workspace form inside an Agency and fills in the name, the Agency, and any optional fields.</li></ol></li><li><ol start="2"><li>System verifies the caller is an active member of that Agency and holds the OWNER role.</li></ol></li><li><ol start="3"><li>System creates the Workspace row with default settings and records the caller as its creator.</li></ol></li><li><ol start="4"><li>System inserts the creator&#39;s membership with role MANAGER - or CREATOR when the MANAGER role is being transferred.</li></ol></li><li><ol start="5"><li>System applies the assignMembers entries, inserting a membership row for each valid entry.</li></ol></li><li><ol start="6"><li>System returns the created Workspace and the user is taken into it; toast <strong>MSG31</strong>.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: name empty -&gt; Display: <strong>MSG02</strong>. 1.a2: The user corrects the field and resubmits.</li><li>1.b1: agencyId missing -&gt; 400 VALIDATION_ERROR, Display: <strong>MSG02</strong>. 1.b2: The user selects an Agency and resubmits.</li><li>2.a1: Caller is not an active member of the target Agency, or is a member but not its OWNER -&gt; 403 NOT_AGENCY_OWNER, toast <strong>MSG39</strong>. 2.a2: The user is returned to the Agency list; the Workspace is not created.</li><li>5.a1: An assignMembers entry references a user outside the Agency -&gt; 403 NOT_AGENCY_MEMBER, toast <strong>MSG39</strong>. 5.a2: The user removes or corrects that entry and resubmits.</li><li>5.b1: An assignMembers entry references a user that does not exist -&gt; USER_NOT_FOUND, toast <strong>MSG38</strong>. 5.b2: The user removes or corrects that entry and resubmits.</li><li>5.c1: Two entries request MANAGER besides the creator -&gt; 409 MANAGER_ALREADY_ASSIGNED, toast <strong>MSG39</strong>. 5.c2: The user reduces the assignment to a single MANAGER and resubmits.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>A Workspace row exists inside the Agency.</li><li>A membership row exists for the creator and for every valid assignMembers entry.</li><li>The new Workspace has exactly one active MANAGER.</li></ul><h4 id="_3-4-13-view-workspace-profile" tabindex="-1">3.4.13 View Workspace Profile <a class="header-anchor" href="#_3-4-13-view-workspace-profile" aria-label="Permalink to &quot;3.4.13 View Workspace Profile&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a Workspace member opens the profile of a Workspace.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Workspace members with role MANAGER, CREATOR, or CLIENT.</li><li><strong>Purpose</strong>: Shows the Workspace&#39;s details - timezone configuration and branding/company information - so members understand which timezone the Workspace runs on and how its branding is configured.</li><li><strong>Interface</strong>: Workspace settings screen - a single combined page that also hosts the update form (FR 3.4.14); there is no separate read-only profile route.</li><li><strong>Data Processing</strong>: The system loads the Workspace and maps the record to a Workspace profile, parsing the stored settings into timezone, default platforms, and report frequency.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Workspace Settings Screen:</p><ul><li>Logo block shown only when the caller can manage the Workspace.</li><li>Form pre-filled with name, timezone, default platforms, report frequency, industry, company size, website, phone, location.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the Workspace record; the caller&#39;s active membership row; the stored settings payload.</li><li><strong>Output</strong>: the Workspace profile - id, name, agencyId, slug, ownerId, settings (timezone, defaultPlatforms, reportFrequency), industry, companySize, website, phone, location, description, branding fields, social links, isActive, createdAt.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29</strong>: Every workspace-scoped resource carries workspaceId; a caller with no active membership cannot read it regardless of system role (except ADMIN). Enforced in two layers: a controller-level role check against the caller&#39;s global role set, and a service-level membership check scoped to this specific Workspace.</li><li><strong>BR-167</strong>: Workspace that does not exist -&gt; 404 WORKSPACE_NOT_FOUND.</li><li><strong>BR-168</strong>: Caller not an active member of that specific Workspace -&gt; 403 WORKSPACE_ACCESS_DENIED.</li><li><strong>BR-169</strong>: Failure to parse the stored settings falls back to empty settings without raising an error.</li><li><strong>BR-170</strong>: There is a single Workspace-level timezone configuration - not one per Client or per Task.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>The Workspace must exist; otherwise 404 WORKSPACE_NOT_FOUND.</li><li>The caller must hold an active membership in that Workspace; otherwise 403 WORKSPACE_ACCESS_DENIED.</li><li>A malformed settings payload must degrade to empty settings rather than fail the request.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>Member opens the Workspace settings screen.</li></ol></li><li><ol start="2"><li>System loads the Workspace; if it does not exist, the request fails with 404 WORKSPACE_NOT_FOUND.</li></ol></li><li><ol start="3"><li>System confirms the caller has an active membership in that Workspace; otherwise the request fails with 403 WORKSPACE_ACCESS_DENIED.</li></ol></li><li><ol start="4"><li>System maps the Workspace to its profile, parsing the stored settings into timezone, default platforms, and report frequency.</li></ol></li><li><ol start="5"><li>Screen displays the Workspace profile, including the Workspace timezone.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: The Workspace does not exist -&gt; 404 WORKSPACE_NOT_FOUND, toast <strong>MSG38</strong>. 2.a2: The member returns to the Workspace list and picks a valid Workspace.</li><li>3.a1: The caller has no active membership in that Workspace -&gt; 403 WORKSPACE_ACCESS_DENIED, toast <strong>MSG40</strong>. 3.a2: The member returns to the Workspace list; only Workspaces they belong to are shown.</li><li>4.a1: Stored settings are malformed -&gt; the screen shows empty settings instead of failing. 4.a2: The member may ask a MANAGER to re-save the settings.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>No data is changed; the Workspace profile is displayed.</li></ul><h4 id="_3-4-14-update-workspace-profile" tabindex="-1">3.4.14 Update Workspace Profile <a class="header-anchor" href="#_3-4-14-update-workspace-profile" aria-label="Permalink to &quot;3.4.14 Update Workspace Profile&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when the MANAGER of a Workspace submits changes to the Workspace profile or settings.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: The MANAGER of the Workspace, and only that role.</li><li><strong>Purpose</strong>: Lets the Workspace MANAGER keep the Workspace&#39;s details and settings accurate with day-to-day operations.</li><li><strong>Interface</strong>: Workspace settings screen - the same page that displays the profile (FR 3.4.13); the edit form and logo control appear on it directly.</li><li><strong>Data Processing</strong>: The system loads the Workspace, merges the supplied fields into the record and settings, and returns the updated Workspace profile.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Workspace Settings Screen, edit section:</p><ul><li>Logo block, shown only when the caller can manage the Workspace; client-side accepts image/jpeg, image/png, image/webp and rejects files over 5 MB before calling the upload endpoint.</li><li>Form pre-filled with the current name, timezone, default platforms, report frequency, industry, company size, website, phone, and location.</li><li>A &quot;Save&quot; action; on success a confirmation toast is shown and the form keeps the newly entered values.</li><li>Out of scope for this FR but on the same screen: a &quot;Save as Template&quot; dialog (FR 3.4.17) and a Danger Zone delete-Workspace block (FR 3.4.15).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional</strong>: name, timezone, defaultPlatforms, reportFrequency (WEEKLY / MONTHLY), industry, companySize, website, phone, location. For the logo control: the uploaded image file.</li><li><strong>System data</strong>: the existing Workspace record and its stored settings; the caller&#39;s role in that Workspace; the stored URL of the uploaded logo.</li><li><strong>Output</strong>: the updated Workspace profile - id, name, agencyId, slug, ownerId, settings, industry, companySize, website, phone, location, description, branding fields, social links, isActive, createdAt.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-25</strong>: Workspace settings and logo can only be updated by MANAGER; all settings fields are optional (partial update).</li><li><strong>BR-35</strong>: The role check re-reads the caller&#39;s role from the database at request time and runs before the not-found lookup. SystemRole.ADMIN bypasses the check.</li><li><strong>BR-171</strong>: The Workspace must exist -&gt; otherwise 404 WORKSPACE_NOT_FOUND.</li><li><strong>BR-172</strong>: Fields not supplied in the request keep their current values; the stored settings are merged rather than replaced.</li><li><strong>BR-173</strong>: A failure while reading the uploaded logo file -&gt; 400 FILE_READ_ERROR.</li><li><strong>BR-174</strong>: The logo is uploaded through its own dedicated action, not through the profile settings update.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>The caller must hold the MANAGER role in that Workspace; otherwise 403 FORBIDDEN.</li><li>The Workspace must exist; otherwise 404 WORKSPACE_NOT_FOUND.</li><li>industry must be a valid WorkspaceIndustry value; companySize must be a valid CompanySize value. Empty required field -&gt; Display: <strong>MSG02</strong>. Exceeding max length -&gt; Display: <strong>MSG03</strong>.</li><li>An unreadable logo file -&gt; 400 FILE_READ_ERROR. The frontend rejects non-image files and files over 5 MB before the request is sent.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>MANAGER opens Workspace settings and edits the name, timezone, default platforms, report frequency, industry, company size, website, phone, or location.</li></ol></li><li><ol start="2"><li>System confirms the caller holds the MANAGER role in that Workspace; otherwise the request fails with 403 FORBIDDEN.</li></ol></li><li><ol start="3"><li>System loads the Workspace; if it does not exist the request fails with 404 WORKSPACE_NOT_FOUND.</li></ol></li><li><ol start="4"><li>System applies the supplied fields and merges the new timezone / default platforms into the stored settings, keeping previous values for fields left out.</li></ol></li><li><ol start="5"><li>System returns the updated Workspace profile; the screen shows a success confirmation, toast <strong>MSG32</strong>. The separate logo upload action, on success, shows toast <strong>MSG94</strong>.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Caller is not the MANAGER of that Workspace -&gt; 403 FORBIDDEN, toast <strong>MSG39</strong>. 2.a2: The caller stays on the same screen with the edit controls hidden.</li><li>3.a1: The Workspace does not exist -&gt; 404 WORKSPACE_NOT_FOUND, toast <strong>MSG38</strong>. 3.a2: The MANAGER returns to the Workspace list.</li><li>3.b1: Logo upload file cannot be read -&gt; 400 FILE_READ_ERROR. 3.b2: The user retries with another file.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The Workspace record and its settings carry the new values; fields not supplied are unchanged.</li><li>When a logo was uploaded, the Workspace holds the new logo location.</li></ul><h4 id="_3-4-15-delete-workspace" tabindex="-1">3.4.15 Delete Workspace <a class="header-anchor" href="#_3-4-15-delete-workspace" aria-label="Permalink to &quot;3.4.15 Delete Workspace&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when an Agency owner confirms deletion of a Workspace by opening Workspace settings and typing the Workspace name in the danger-zone confirmation dialog.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Agency OWNER.</li><li><strong>Purpose</strong>: Lets the owner remove a Workspace that is no longer used while keeping it recoverable for 30 days.</li><li><strong>Interface</strong>: A &quot;Danger Zone&quot; block inside Workspace settings, visible only when the caller can manage, with a Delete button that opens a confirmation dialog requiring the user to type the Workspace name before the destructive action is enabled. There is currently no Restore entry point in the frontend - restore exists only as a backend endpoint.</li><li><strong>Data Processing</strong>: The system marks the Workspace as soft-deleted (status = SOFT_DELETED, deletedAt = now()); restoring within 30 days reverses this. Deleting only flips the Workspace&#39;s own status/timestamp fields - it does not cascade to Task/Campaign/Material records; those remain ACTIVE and are not automatically hidden. Access is not revoked mid-session either.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Delete Workspace Dialog:</p><ul><li>A destructive confirmation dialog opened from the Danger Zone in Workspace settings, visible to the owner only.</li><li>The dialog requires the user to type the Workspace name before &quot;Confirm Delete&quot; is enabled; a Cancel button closes it without action.</li><li>On success, a success toast is shown and the user is navigated to the Workspace list; on failure, an error toast is shown.</li><li>No restore screen exists in the frontend today - the restore capability is backend-only.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the caller&#39;s authenticated identity; the typed Workspace name confirming the action.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the Workspace record with its status and deletion timestamp; the deletion window allowed for restoration.</li><li><strong>Output</strong>: confirmation that the Workspace has been soft-deleted; on restore, the restored Workspace profile.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-26</strong>: Delete workspace is OWNER-only, implemented here as Agency OWNER. Soft-delete vs hard-delete, and the interaction with an active paid subscription, remain TBD - the implemented code only ever soft-deletes.</li><li><strong>BR-175</strong>: A caller who is not the Agency OWNER, including the Workspace MANAGER -&gt; 403 FORBIDDEN.</li><li><strong>BR-176</strong>: Restoring later than 30 days after deletion -&gt; 410 RESTORE_WINDOW_EXPIRED.</li><li><strong>BR-177</strong>: Restoring a Workspace whose status is not SOFT_DELETED -&gt; 400 WORKSPACE_NOT_DELETED.</li><li><strong>BR-178</strong>: Known gap: deleteWorkspace only sets the Workspace&#39;s own status/deletedAt - there is no cascade write to Task/Campaign/Material records. Member/Client access is not revoked mid-session; the deleted Workspace simply no longer appears in the Workspace list. If cascading to inactive is required, it needs new code.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>The typed Workspace name must match the Workspace being deleted before the action is enabled.</li><li>The caller must be the Agency OWNER; otherwise 403 FORBIDDEN, toast <strong>MSG39</strong>.</li><li>The Workspace must exist; otherwise 404 WORKSPACE_NOT_FOUND, toast <strong>MSG38</strong>.</li><li>The caller must belong to the Workspace&#39;s Agency; otherwise toast <strong>MSG40</strong>.</li><li>Restore is allowed only when the Workspace&#39;s status is SOFT_DELETED and within 30 days of the deletion timestamp.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>Owner opens Workspace settings and chooses Delete in the Danger Zone.</li></ol></li><li><ol start="2"><li>Dialog asks the owner to type the Workspace name to confirm; the Confirm Delete button stays disabled until the typed value matches.</li></ol></li><li><ol start="3"><li>System confirms the caller is the Agency OWNER; otherwise the request fails with 403 FORBIDDEN.</li></ol></li><li><ol start="4"><li>System marks the Workspace as soft-deleted and records the deletion timestamp.</li></ol></li><li><ol start="5"><li>Task/Campaign/Material records inside the Workspace are left as-is - no cascade occurs.</li></ol></li><li><ol start="6"><li>The Workspace disappears from active listings; success toast shown, user navigated to the Workspace list. It becomes restorable for 30 days via the backend endpoint only.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Caller is not the Agency OWNER, even when they manage the Workspace -&gt; 403 FORBIDDEN, toast <strong>MSG39</strong>. 3.a2: The caller returns to Workspace settings without deleting.</li><li>3.b1: The Workspace does not exist -&gt; 404 WORKSPACE_NOT_FOUND, toast <strong>MSG38</strong>. 3.b2: The caller returns to the Workspace list.</li><li>3.c1: The caller does not belong to this Workspace&#39;s Agency -&gt; toast <strong>MSG40</strong>. 3.c2: The caller is returned to their own Workspace list.</li><li>Restoring a Workspace that is not currently soft-deleted -&gt; 400 WORKSPACE_NOT_DELETED.</li><li>Restoring after the 30-day window -&gt; 410 RESTORE_WINDOW_EXPIRED.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The Workspace is marked soft-deleted and is hidden from active listings.</li><li>The Workspace&#39;s Task/Campaign/Material records are unaffected - no cascade exists today.</li><li>The Workspace remains restorable for 30 days via the backend restore endpoint (no FE screen currently exposes this).</li></ul><h4 id="_3-4-16-leave-workspace" tabindex="-1">3.4.16 Leave Workspace <a class="header-anchor" href="#_3-4-16-leave-workspace" aria-label="Permalink to &quot;3.4.16 Leave Workspace&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when an active member of a Workspace confirms leaving that Workspace.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any active member of the Workspace - MANAGER, CREATOR, or CLIENT - acting on their own membership only.</li><li><strong>Purpose</strong>: Lets a member leave a Workspace they no longer take part in while keeping their Agency membership, so they can still join other Workspaces.</li><li><strong>Interface</strong>: &quot;Leave Workspace&quot; action in Workspace settings or the members screen, shown only to the signed-in user themselves, followed by a confirmation dialog.</li><li><strong>Data Processing</strong>: The system locates the caller&#39;s own active membership in the Workspace and marks it inactive, without touching the caller&#39;s Agency membership.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Leave Workspace Dialog:</p><ul><li>A &quot;Leave Workspace&quot; action inside Workspace settings or the members screen, visible only to the signed-in user.</li><li>A confirmation dialog explaining that the member leaves this Workspace but remains in the Agency.</li><li>A blocked state with a clear message when the member is the last MANAGER of the Workspace.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the caller&#39;s authenticated identity, taken from the session principal.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the caller&#39;s active membership row in that Workspace; the count of active MANAGERs in the Workspace.</li><li><strong>Output</strong>: confirmation that the membership has been deactivated; no other data is returned.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29</strong>: The caller identity always comes from the session principal and the action applies only to the caller&#39;s own membership row; no other member can be targeted.</li><li><strong>BR-28 / BR-30</strong>: Leaving is a soft delete (isActive=false); the caller loses access immediately because every scoped query re-checks membership. The caller&#39;s Agency membership is never modified. A MANAGER cannot leave if they are the last active MANAGER of the Workspace - the MANAGER role must be handed over first through FR 3.4.20.</li><li><strong>BR-31</strong>: The Workspace role set assignable at Workspace level is MANAGER, CREATOR, CLIENT (OWNER exists only at Agency level); the last-MANAGER guard applies only when the membership being deactivated carries the MANAGER role.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>The caller must hold an active membership in that Workspace; otherwise 403 WORKSPACE_ACCESS_DENIED, toast <strong>MSG40</strong>.</li><li>The caller must not be the only active MANAGER of the Workspace; otherwise 409 LAST_MANAGER_CANNOT_BE_REMOVED, toast <strong>MSG37</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>Member opens Workspace settings or the members screen and chooses &quot;Leave Workspace&quot;.</li></ol></li><li><ol start="2"><li>Member confirms in the dialog.</li></ol></li><li><ol start="3"><li>System looks up the caller&#39;s own active membership in the Workspace; if none exists the request fails with 403 WORKSPACE_ACCESS_DENIED.</li></ol></li><li><ol start="4"><li>System applies the last-MANAGER guard: members who are not MANAGER pass, and a MANAGER passes when another active MANAGER exists.</li></ol></li><li><ol start="5"><li>System marks the membership inactive.</li></ol></li><li><ol start="6"><li>The member is taken out of the Workspace back to the Workspace list, while remaining in the Agency and in their other Workspaces; toast <strong>MSG36</strong>.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Caller has no active membership in that Workspace -&gt; 403 WORKSPACE_ACCESS_DENIED, toast <strong>MSG40</strong>. 3.a2: The caller returns to the Workspace list; the Workspace they tried to leave does not appear.</li><li>4.a1: Caller is the only active MANAGER of the Workspace -&gt; 409 LAST_MANAGER_CANNOT_BE_REMOVED, toast <strong>MSG37</strong>. 4.a2: Another MANAGER must be assigned first through FR 3.4.20, then the caller retries leaving.</li><li>4.b1: A CREATOR or CLIENT leaves while other members remain -&gt; the request always succeeds. 4.b2: The member is removed from the Workspace and returned to the Workspace list.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The caller&#39;s membership in the Workspace is inactive and the Workspace no longer appears in their list.</li><li>The caller&#39;s Agency membership is untouched; they remain in the Agency and in their other Workspaces.</li></ul><h4 id="_3-4-17-save-workspace-template" tabindex="-1">3.4.17 Save Workspace Template <a class="header-anchor" href="#_3-4-17-save-workspace-template" aria-label="Permalink to &quot;3.4.17 Save Workspace Template&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a signed-in Agency member saves the configuration of an existing Workspace as a template.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any signed-in member of the Agency; no specific role restriction is applied.</li><li><strong>Purpose</strong>: Lets a member store a Workspace configuration as a reusable template so similar Workspaces can be created faster later.</li><li><strong>Interface</strong>: A &quot;Save as Template&quot; modal opened from Workspace settings, plus a &quot;View all templates&quot; link to a separate templates list page. There is no separate detail route/page - the templates list implements detail as an inline expand row.</li><li><strong>Data Processing</strong>: The system stores the template with the configuration snapshot captured from the Workspace, scoped automatically to the caller&#39;s Agency, with creator identity taken from the authenticated session.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Save Workspace Template Screen:</p><ul><li>A &quot;Save as Template&quot; button plus a &quot;View all templates&quot; link, both inside Workspace settings, shown only when the caller can manage.</li><li>The &quot;Save as Template&quot; action opens a modal with a template name input; the configSnapshot is built automatically from the current Workspace&#39;s timezone, defaultPlatforms, and reportFrequency - there is no free-form configSnapshot input and no sourceWorkspaceId picker.</li><li>The templates list page shows each template&#39;s name and creation date; clicking the name toggles an inline expand showing the raw configSnapshot text; a delete button removes it.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: name; configSnapshot (a JSON snapshot of the Workspace configuration).</li><li><strong>Input optional</strong>: sourceWorkspaceId.</li><li><strong>System data</strong>: the caller&#39;s authenticated identity; the Agency the caller belongs to; the creation timestamp.</li><li><strong>Output</strong>: the stored template - id, agencyId, name, sourceWorkspaceId, configSnapshot, createdBy, createdAt.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29</strong>: The Agency and the creator of the template are taken automatically from the caller&#39;s session and never from the request payload; a template is scoped to the caller&#39;s Agency.</li><li><strong>BR-02</strong>: Templates are a standalone resource, not nested inside an Agency or a Workspace; available actions are create, list, delete, and inline-expand-to-view.</li><li><strong>BR-03</strong>: name or configSnapshot empty -&gt; 400 VALIDATION_ERROR.</li><li><strong>BR-04</strong>: Requesting or deleting a template that does not exist -&gt; 404 NOT_FOUND.</li><li><strong>BR-05</strong>: No specific role restriction is currently applied to these actions.</li><li><strong>BR-06</strong>: A template is independent of its source Workspace - it remains available even after that Workspace is deleted.</li><li><strong>BR-179</strong>: getTemplate and deleteTemplate both enforce that the caller owns the template&#39;s Agency; otherwise 403 FORBIDDEN.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>name must not be empty; otherwise 400 VALIDATION_ERROR, <strong>MSG02</strong>.</li><li>configSnapshot must not be empty; otherwise 400 VALIDATION_ERROR, <strong>MSG02</strong>.</li><li>The template must exist for delete/get; otherwise 404 NOT_FOUND, toast <strong>MSG38</strong>.</li><li>Getting or deleting a template belonging to a different Agency -&gt; 403 FORBIDDEN.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>Member opens Workspace settings and clicks &quot;Save as Template&quot;, opening a modal.</li></ol></li><li><ol start="2"><li>Member fills in the template name; the configSnapshot is built automatically from the current Workspace&#39;s timezone/defaultPlatforms/reportFrequency, and sourceWorkspaceId is set to the current workspace&#39;s id.</li></ol></li><li><ol start="3"><li>System validates that the name and snapshot are not empty.</li></ol></li><li><ol start="4"><li>System resolves the caller&#39;s owned Agency and attaches agencyId/createdBy automatically.</li></ol></li><li><ol start="5"><li>System stores the template and returns it; a success toast is shown and the modal closes.</li></ol></li><li><ol start="6"><li>Member can later open the templates list to expand one inline and view its configSnapshot, or delete it.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: name empty -&gt; 400 VALIDATION_ERROR, Display: <strong>MSG02</strong>. 3.a2: The user supplies a name and resubmits.</li><li>3.b1: configSnapshot empty -&gt; 400 VALIDATION_ERROR, Display: <strong>MSG02</strong>. 3.b2: The user captures the configuration and resubmits (cannot happen in the current UI since configSnapshot is always auto-built).</li><li>6.a1: Delete/get requested for a template that does not exist -&gt; 404 NOT_FOUND, toast <strong>MSG38</strong>. 6.a2: The user returns to the template list, which no longer shows that entry.</li><li>6.b1: The source Workspace is deleted after the template was saved -&gt; no error is raised. 6.b2: The template still exists and remains listable.</li><li>6.c1: Delete requested for a template belonging to another Agency -&gt; 403 FORBIDDEN. 6.c2: The user has no access; the template is unaffected.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>A template exists within the caller&#39;s Agency with the captured configuration snapshot.</li><li>The template remains available independently of the source Workspace.</li></ul><h4 id="_3-4-18-view-workspace-members" tabindex="-1">3.4.18 View Workspace Members <a class="header-anchor" href="#_3-4-18-view-workspace-members" aria-label="Permalink to &quot;3.4.18 View Workspace Members&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when a Workspace member opens the members screen of a Workspace.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Workspace members with role MANAGER, CREATOR, or CLIENT.</li><li><strong>Purpose</strong>: Shows who takes part in the Workspace and the role each member holds.</li><li><strong>Interface</strong>: Workspace members screen, listing members with their roles.</li><li><strong>Data Processing</strong>: The system loads the Workspace, confirms the caller is an active member of that same Workspace, then lists every member of the Workspace together with the display name and email of each member&#39;s user or client profile.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Workspace Members Screen:</p><ul><li>A table of members with name, email, role, and the date each member joined.</li><li>Role badges for MANAGER, CREATOR, and CLIENT.</li><li>Active members only; members who have left or were removed do not appear.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the Workspace record; the caller&#39;s active membership row; the Workspace&#39;s active membership rows; the user records and client profiles those memberships reference.</li><li><strong>Output</strong>: the list of members - id, workspaceId, userId, fullName, email, clientProfileId, role, joinedAt, isActive. Role is one of MANAGER, CREATOR, CLIENT - there is no OWNER at Workspace level.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29</strong>: The Workspace must exist; otherwise 404 WORKSPACE_NOT_FOUND. A caller with no active membership in that Workspace cannot read it regardless of system role (except ADMIN).</li><li><strong>BR-30</strong>: The caller must be an active member of the very Workspace being viewed; otherwise 403 WORKSPACE_ACCESS_DENIED. This is the same re-check that cuts off access once a member is removed or leaves.</li><li><strong>BR-31</strong>: The role list at Workspace level is MANAGER, CREATOR, CLIENT; OWNER is not a Workspace role.</li><li><strong>BR-35</strong>: Role/permission checks re-read the caller&#39;s role from the DB at request time; SystemRole.ADMIN bypasses the membership check.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>The Workspace must exist; otherwise 404 WORKSPACE_NOT_FOUND, toast <strong>MSG38</strong>.</li><li>The caller must hold an active membership in that Workspace; otherwise 403 WORKSPACE_ACCESS_DENIED, toast <strong>MSG40</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>Member opens the Workspace members screen.</li></ol></li><li><ol start="2"><li>System loads the Workspace; if it does not exist the request fails with 404 WORKSPACE_NOT_FOUND.</li></ol></li><li><ol start="3"><li>System confirms the caller holds an active membership in that Workspace; otherwise the request fails with 403 WORKSPACE_ACCESS_DENIED.</li></ol></li><li><ol start="4"><li>System reads the Workspace&#39;s active membership rows and resolves the display name and email of each member from the referenced user record or client profile.</li></ol></li><li><ol start="5"><li>Screen renders the member table with each member&#39;s role and join date.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Workspace does not exist -&gt; 404 WORKSPACE_NOT_FOUND, toast <strong>MSG38</strong>. 2.a2: The member returns to the Workspace list.</li><li>3.a1: Caller is not an active member of that Workspace -&gt; 403 WORKSPACE_ACCESS_DENIED, toast <strong>MSG40</strong>. 3.a2: The member returns to the Workspace list; the Workspace they tried to view does not appear.</li><li>4.a1: A member has no linked user account but is attached through a client profile -&gt; the client profile&#39;s display name is shown and the email is empty. 4.a2: The row renders normally with the remaining columns unaffected.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>No data is changed; the Workspace members are displayed.</li></ul><h4 id="_3-4-19-add-workspace-member" tabindex="-1">3.4.19 Add Workspace Member <a class="header-anchor" href="#_3-4-19-add-workspace-member" aria-label="Permalink to &quot;3.4.19 Add Workspace Member&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when the MANAGER of a Workspace adds a member, either by inviting an email address or by assigning a user who already belongs to the Agency.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: The MANAGER of the Workspace, and only that role.</li><li><strong>Purpose</strong>: Brings people into the Workspace with the right role, either by inviting them by email or by directly assigning people who are already in the Agency.</li><li><strong>Interface</strong>: &quot;Add Member&quot; action on the members screen, offering two paths - &quot;Invite by email&quot; and &quot;Assign from Agency&quot;.</li><li><strong>Data Processing</strong>: For an invitation the system records a pending invitation and sends an email; for an assignment the system creates active memberships immediately and reports which users were added and which were skipped because they were already active members.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Add Workspace Member Screen:</p><ul><li>An &quot;Add Member&quot; action on the members screen.</li><li>An &quot;Invite by email&quot; tab with email, role, and an optional note.</li><li>An &quot;Assign from Agency&quot; tab listing existing Agency members with a role choice per person.</li><li>After an assignment, the result shows the members added and a notice for the users skipped because they were already members.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the caller&#39;s authenticated identity. For an invitation: email and role. For an assignment: at least one entry of {userId, role}.</li><li><strong>Input optional</strong>: note (invitation only).</li><li><strong>System data</strong>: the caller&#39;s role in the Workspace; the count of active MANAGERs in the Workspace; whether the email already has an active membership or a pending invitation; the Agency membership of each assigned user.</li><li><strong>Output</strong>: for an invitation, an acknowledgement with no content. For an assignment, the members added - id, workspaceId, userId, fullName, email, clientProfileId, role, joinedAt, isActive - together with skippedUserIds. Role is one of MANAGER, CREATOR, CLIENT.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-27</strong>: Invite path - only MANAGER may invite; an already-active member cannot be re-invited (409 ALREADY_IN_WORKSPACE, checked first); a second invite is blocked while a pending unexpired invitation exists for the same email (409 INVITATION_ALREADY_PENDING, checked second); the invitation token is a random UUID with an expiry window.</li><li><strong>BR-35</strong>: The role check re-reads the caller&#39;s role from the DB at request time; SystemRole.ADMIN bypasses the check. The role check (MANAGER required) runs before any service-level guard.</li><li><strong>BR-02</strong>: The invitation path does not create a membership immediately - it records a pending invitation that the invitee must accept before becoming a member.</li><li><strong>BR-05</strong>: Requesting the MANAGER role while the Workspace already has an active MANAGER -&gt; 409 MANAGER_ALREADY_ASSIGNED, checked third, on both paths.</li><li><strong>BR-06</strong>: The assignment path creates active memberships immediately and needs no acceptance step.</li><li><strong>BR-07</strong>: An assignment entry whose user already has an active membership is skipped without error and reported in skippedUserIds; the rest of the batch still runs.</li><li><strong>BR-08</strong>: An assignment entry whose user is not a member of the Agency -&gt; 403 NOT_AGENCY_MEMBER.</li><li><strong>BR-09</strong>: An assignment entry whose user record does not exist -&gt; USER_NOT_FOUND.</li><li><strong>BR-31</strong>: There are three workspace roles - MANAGER, CREATOR, CLIENT; there is no Workspace-level OWNER (OWNER exists only at Agency level). Invited or assigned roles must be one of these three.</li><li><strong>BR-32</strong>: Role assignment happens at invite time; the role is stored on the invitation and carried to the member row on acceptance.</li><li><strong>BR-11</strong>: Roles are independent per Workspace - the same user may hold a different role in another Workspace of the same Agency.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller must be the MANAGER of that Workspace; otherwise 403 FORBIDDEN. Display: <strong>MSG39</strong>.</li><li>email empty -&gt; Display: <strong>MSG02</strong>.</li><li>role empty -&gt; Display: <strong>MSG02</strong>.</li><li>Invitation: email must be a well-formed email address; otherwise Display: <strong>MSG04</strong>.</li><li>Invitation: role must be one of MANAGER, CREATOR, CLIENT; otherwise Display: <strong>MSG95</strong>.</li><li>Assignment: the member list must contain at least one entry; otherwise 400 VALIDATION_ERROR, Display: <strong>MSG02</strong>.</li><li>Assignment: every userId must belong to an Agency member; otherwise 403 NOT_AGENCY_MEMBER.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>MANAGER opens the members screen and chooses &quot;Add Member&quot;.</li></ol></li><li><ol start="2"><li>On the invite path, the MANAGER enters an email, a role, and an optional note; on the assign path, the MANAGER picks one or more existing Agency members and a role for each.</li></ol></li><li><ol start="3"><li>System confirms the caller holds the MANAGER role in the Workspace; otherwise the request fails with 403 FORBIDDEN.</li></ol></li><li><ol start="4"><li>Invite path: system normalises the email, checks for an existing active membership and for a pending invitation, and applies the single-MANAGER rule when the role is MANAGER.</li></ol></li><li><ol start="5"><li>Invite path: system records a pending invitation with an expiry and sends the invitation email; toast <strong>MSG33</strong>.</li></ol></li><li><ol start="6"><li>Assign path: system validates each entry against Agency membership, skips users who are already active members, applies the single-MANAGER rule, and creates active memberships immediately.</li></ol></li><li><ol start="7"><li>Assign path: system returns the members added together with the identifiers of the users skipped.</li></ol></li><li><ol start="8"><li>Screen refreshes the member list with the members added and can show a notice for the skipped users.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Caller is not the MANAGER of the Workspace -&gt; 403 FORBIDDEN, toast <strong>MSG39</strong>. 3.a2: The screen blocks the action.</li><li>4.a1: Invitation for an email that already has an active membership -&gt; 409 ALREADY_IN_WORKSPACE, toast <strong>MSG34</strong>. 4.a2: The MANAGER checks the existing member list instead of re-inviting.</li><li>4.b1: Invitation for an email that already has a pending, unexpired invitation -&gt; 409 INVITATION_ALREADY_PENDING, toast <strong>MSG35</strong>. 4.b2: The MANAGER waits for the pending invitation to be accepted or expire.</li><li>4.c1: MANAGER role requested while the Workspace already has an active MANAGER -&gt; 409 MANAGER_ALREADY_ASSIGNED, Display: <strong>MSG95</strong>. 4.c2: The MANAGER picks CREATOR or CLIENT instead, or hands over the MANAGER role first.</li><li>Assignment entry whose user is outside the Agency -&gt; 403 NOT_AGENCY_MEMBER.</li><li>Assignment entry whose user does not exist -&gt; USER_NOT_FOUND.</li><li>Assignment where some users are already active members -&gt; those identifiers appear in skippedUserIds, no error is raised, and the rest of the batch is processed.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Invite path: a pending invitation exists for the email with an expiry date, and the invitation email has been dispatched.</li><li>Assign path: active membership rows exist for every valid entry, and the identifiers of the skipped users have been reported.</li><li>The Workspace still has exactly one active MANAGER.</li></ul><h4 id="_3-4-20-update-workspace-member-role" tabindex="-1">3.4.20 Update Workspace Member Role <a class="header-anchor" href="#_3-4-20-update-workspace-member-role" aria-label="Permalink to &quot;3.4.20 Update Workspace Member Role&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when the MANAGER of a Workspace changes the role of one of its members.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: The MANAGER of the Workspace, and only that role.</li><li><strong>Purpose</strong>: Lets the MANAGER adjust a member&#39;s role to match the work actually being done, including handing over the MANAGER role.</li><li><strong>Interface</strong>: A role selector in the member table, offering MANAGER, CREATOR, and CLIENT.</li><li><strong>Data Processing</strong>: The system loads the member, applies the single-MANAGER guards, updates the role, and returns the updated member.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Update Member Role Screen:</p><ul><li>The member table on the members screen.</li><li>A role selector per member with the values MANAGER, CREATOR, CLIENT.</li><li>A blocked state with a clear message when the change would leave the Workspace without a MANAGER or would create a second one.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the member identifier; the new role.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the caller&#39;s role in the Workspace; the member record and its current role; the count of active MANAGERs in the Workspace; the member&#39;s user record for building the response.</li><li><strong>Output</strong>: the updated member - id, workspaceId, userId, fullName, email, clientProfileId, role, joinedAt, isActive, carrying the new role.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-35</strong>: The role check re-reads the caller&#39;s role from the DB at request time; SystemRole.ADMIN bypasses the check. Only MANAGER may change roles; any other caller -&gt; 403 FORBIDDEN. This runs before any service-level guard.</li><li><strong>BR-33</strong>: A role change affects the current Workspace only - it does not carry over to the same member&#39;s roles in other Workspaces of the Agency.</li><li><strong>BR-83</strong>: Last-MANAGER guard on demotion - if the member is the only active MANAGER of the Workspace and the new role is not MANAGER, the request is blocked with 409 LAST_MANAGER_CANNOT_BE_REMOVED; another MANAGER must be in place first. Checked before the duplicate-MANAGER guard.</li><li><strong>BR-87</strong>: Duplicate-MANAGER guard on promotion, checked second - if the new role is MANAGER and the member is not currently a MANAGER, the request is blocked with 409 MANAGER_ALREADY_ASSIGNED when the Workspace already has another active MANAGER.</li><li><strong>BR-29</strong>: The member lookup is scoped to the Workspace; a member that does not exist, is not active, or belongs to another Workspace -&gt; 404 NOT_FOUND.</li><li><strong>BR-31</strong>: The assignable workspace roles are MANAGER, CREATOR, CLIENT; there is no Workspace-level OWNER.</li><li><strong>BR-82</strong>: role must be one of the enum values; any other value is rejected.</li><li><strong>BR-180</strong>: There is no exception for changing one&#39;s own role - a MANAGER acting on themselves is subject to the same guards as any other member.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller must be the MANAGER of that Workspace; otherwise 403 FORBIDDEN. Toast <strong>MSG39</strong>.</li><li>role empty -&gt; Display: <strong>MSG02</strong>.</li><li>The member must exist, be active, and belong to that Workspace; otherwise 404 NOT_FOUND. Toast <strong>MSG38</strong>.</li><li>The new role must be one of MANAGER, CREATOR, CLIENT; otherwise Display: <strong>MSG95</strong>.</li><li>Demoting the only active MANAGER -&gt; 409 LAST_MANAGER_CANNOT_BE_REMOVED. Toast <strong>MSG96</strong>.</li><li>Promoting to MANAGER while another active MANAGER exists -&gt; 409 MANAGER_ALREADY_ASSIGNED. Display: <strong>MSG95</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>MANAGER opens the members screen and picks a new role for a member in the role selector.</li></ol></li><li><ol start="2"><li>System confirms the caller holds the MANAGER role in that Workspace; otherwise the request fails with 403 FORBIDDEN.</li></ol></li><li><ol start="3"><li>System loads the member and checks that it exists, is active, and belongs to that Workspace; otherwise the request fails with 404 NOT_FOUND.</li></ol></li><li><ol start="4"><li>System applies the guards in order: the last-MANAGER guard when demoting the only active MANAGER, then the duplicate-MANAGER guard when promoting to MANAGER while another active MANAGER exists.</li></ol></li><li><ol start="5"><li>System stores the new role on the membership and returns the updated member.</li></ol></li><li><ol start="6"><li>Screen refreshes the role shown for that member.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Caller is not the MANAGER of that Workspace -&gt; 403 FORBIDDEN, toast <strong>MSG39</strong>. 2.a2: The screen blocks the action.</li><li>3.a1: Member does not exist, is not active, or belongs to another Workspace -&gt; 404 NOT_FOUND, toast <strong>MSG38</strong>. 3.a2: The screen refreshes the member list.</li><li>4.a1: Demoting the only active MANAGER to CREATOR or CLIENT -&gt; 409 LAST_MANAGER_CANNOT_BE_REMOVED, toast <strong>MSG96</strong>. 4.a2: The MANAGER hands the MANAGER role to another member first, then retries.</li><li>4.b1: Promoting a member to MANAGER while the Workspace already has an active MANAGER -&gt; 409 MANAGER_ALREADY_ASSIGNED, Display: <strong>MSG95</strong>. 4.b2: The MANAGER demotes the current MANAGER first, or picks a different role.</li><li>A MANAGER demotes themselves -&gt; allowed when at least one other MANAGER remains; blocked with 409 LAST_MANAGER_CANNOT_BE_REMOVED when they are the only MANAGER.</li><li>A role change between CREATOR and CLIENT -&gt; always allowed.</li><li>Setting the role to the value it already holds -&gt; allowed; no guard blocks a no-op change.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The member holds the new role in this Workspace only.</li><li>The Workspace still has exactly one active MANAGER.</li></ul><h4 id="_3-4-21-remove-workspace-member" tabindex="-1">3.4.21 Remove Workspace Member <a class="header-anchor" href="#_3-4-21-remove-workspace-member" aria-label="Permalink to &quot;3.4.21 Remove Workspace Member&quot;">​</a></h4><p><strong>Function Trigger</strong></p><p>Begins when the MANAGER of a Workspace confirms removal of a member from that Workspace.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: The MANAGER of the Workspace, and only that role.</li><li><strong>Purpose</strong>: Lets the MANAGER take a member out of the Workspace while the member stays in the Agency and can still join other Workspaces.</li><li><strong>Interface</strong>: A Remove action per member in the member table, followed by a confirmation dialog.</li><li><strong>Data Processing</strong>: The system loads the member, applies the last-MANAGER guard, and marks the membership inactive without touching the member&#39;s Agency membership.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Remove Member Dialog:</p><ul><li>A Remove action per member in the members table.</li><li>A confirmation dialog naming the member being removed.</li><li>A blocked state with a clear message when the member is the only active MANAGER of the Workspace.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the member identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the caller&#39;s role in the Workspace; the member record and its role; the count of active MANAGERs in the Workspace.</li><li><strong>Output</strong>: confirmation that the membership has been deactivated; no other data is returned.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-35</strong>: The role check re-reads the caller&#39;s role from the DB at request time; SystemRole.ADMIN bypasses the check. Only MANAGER may remove a member; any other caller -&gt; 403 FORBIDDEN. Runs before any service-level guard.</li><li><strong>BR-28</strong>: Remove member - only MANAGER may remove; the last remaining active MANAGER cannot be removed or changed away from MANAGER; removal is a soft-delete (isActive=false), not a row deletion. The member&#39;s Agency membership is never modified.</li><li><strong>BR-30</strong>: A removed member loses access immediately because every scoped query re-checks membership.</li><li><strong>BR-28 (last-MANAGER guard)</strong>: removing a member whose role is MANAGER is blocked with 409 LAST_MANAGER_CANNOT_BE_REMOVED when that member is the only active MANAGER of the Workspace. The same guard is shared with FR 3.4.16 Leave Workspace and FR 3.4.20 Update Workspace Member Role.</li><li><strong>BR-29</strong>: The member lookup is scoped to the Workspace; a member that does not exist, is not active, or belongs to another Workspace -&gt; 404 NOT_FOUND.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller must be the MANAGER of that Workspace; otherwise 403 FORBIDDEN. Toast <strong>MSG39</strong>.</li><li>The member must exist, be active, and belong to that Workspace; otherwise 404 NOT_FOUND. Toast <strong>MSG38</strong>.</li><li>Removing the only active MANAGER of the Workspace -&gt; 409 LAST_MANAGER_CANNOT_BE_REMOVED. Toast <strong>MSG37</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>MANAGER opens the members screen and chooses Remove for a member.</li></ol></li><li><ol start="2"><li>MANAGER confirms in the dialog.</li></ol></li><li><ol start="3"><li>System confirms the caller holds the MANAGER role in that Workspace; otherwise the request fails with 403 FORBIDDEN.</li></ol></li><li><ol start="4"><li>System loads the member and checks that it exists, is active, and belongs to that Workspace; otherwise the request fails with 404 NOT_FOUND.</li></ol></li><li><ol start="5"><li>System applies the last-MANAGER guard: members who are not MANAGER pass, and a MANAGER passes only when another active MANAGER exists.</li></ol></li><li><ol start="6"><li>System marks the membership inactive; the member disappears from the active member list; toast <strong>MSG36</strong>.</li></ol></li><li><ol start="7"><li>The member&#39;s Agency membership is untouched - they remain in the Agency and in any other Workspace they take part in.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Caller is not the MANAGER of that Workspace -&gt; 403 FORBIDDEN, toast <strong>MSG39</strong>. 3.a2: The screen blocks the action.</li><li>4.a1: Member does not exist, is not active, or belongs to another Workspace -&gt; 404 NOT_FOUND, toast <strong>MSG38</strong>. 4.a2: The screen refreshes the member list.</li><li>5.a1: Removing the only active MANAGER of the Workspace -&gt; 409 LAST_MANAGER_CANNOT_BE_REMOVED, toast <strong>MSG37</strong>. 5.a2: The MANAGER assigns another member as MANAGER first, then retries the removal.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The member&#39;s membership in the Workspace is inactive and the Workspace no longer appears in their list.</li><li>The member&#39;s Agency membership is untouched; they remain in the Agency and in their other Workspaces.</li><li>The Workspace still has exactly one active MANAGER.</li></ul>',485)])])}const u=t(n,[["render",r]]);export{p as __pageData,u as default};
